window.MG_LAZY_DATA["data/lazy/owner-courses/b003-f140035d23d30f59.json"]={sha256:"f140035d23d30f5995de96b54a7a9ff9fd50f23b098cc490055eb31f3a922b34",value:{"id":"b003","category":"structures","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"languageCoverage":["zh-TW","en"],"sourceIds":["v6-akashi-overview","v6-akashi-engineering","v6-akashi-maintenance","v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"stages":[{"id":"b003-stage01","order":1,"steps":[{"id":"b003-v6-01","sequence":1,"order":1,"sourceIds":["v6-akashi-overview","v6-akashi-engineering"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":[],"title":"畫出海峽限制圖","titleEn":"Map strait constraints","objective":"區分航道淨空與結構跨距的需求。","objectiveEn":"Distinguish navigation-clearance needs from structural span requirements.","instruction":"自繪兩岸、航道和候選塔位，另以符號標出深水與強潮流區。為每一個塔位寫出一項須由海事或地質資料確認的限制。","instructionEn":"Sketch the shores, navigation corridor and candidate tower locations; mark deep water and strong currents separately. For each tower location, name a constraint requiring marine or geological evidence.","observation":"比較塔位移動是否同時改變航道餘裕、側跨與施工可達性。","observationEn":"Observe whether moving a tower changes navigation space, side spans and construction access together.","failure":"只保留最短跨距，卻把基礎放入航道或未調查地層。","failureEn":"Minimizing span alone can place foundations in a navigation corridor or uninvestigated ground.","check":"提交有圖例的限制圖，至少保留兩項尚待查證的資料。","checkEn":"Submit a keyed constraint map with at least two unresolved evidence needs.","knowledge":[{"id":"b003-v6-01-k1","title":"多目標選址","titleEn":"Multi-objective siting","text":"塔位同時影響結構、航運和施工；跨距不是唯一決策量。","textEn":"Tower placement affects structure, navigation and construction; span is only one decision variable."},{"id":"b003-v6-01-k2","title":"資料不確定性","titleEn":"Data uncertainty","text":"未量測的水深或地層不能因示意圖畫得完整就視為已確認。","textEn":"A complete-looking sketch does not verify unmeasured depth or ground conditions."}],"quiz":{"options":["航道、地盤與施工限制是否不同","只比較總橋重，認為其可代表所有場址限制","先假定兩地地盤完全相同"],"optionsEn":["Differences in navigation, ground and construction constraints","Compare total bridge weight as if it represented every site constraint","Assume identical ground conditions first"],"answer":0,"question":"兩個塔位方案跨距相近，下一個合理比較是什麼？","questionEn":"Two tower layouts have similar spans. What should be compared next?","explanation":"相近的跨距不代表相同的外部條件，必須比較限制與證據缺口。","explanationEn":"Similar spans do not imply similar external conditions; compare constraints and evidence gaps."}},{"id":"b003-v6-02","sequence":2,"order":2,"sourceIds":["v6-akashi-overview"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b003-v6-01"],"title":"追蹤懸索橋載荷路徑","titleEn":"Trace the suspension load path","objective":"辨認吊索、主纜、塔與錨碇的不同角色。","objectiveEn":"Identify the distinct roles of hangers, main cables, towers and anchorages.","instruction":"在自繪側視圖把一個橋面載荷依序連到吊索及主纜，再分別追蹤塔的支承和端部錨碇的反力。另畫一條溫度伸縮方向箭頭。","instructionEn":"On a side-view sketch, trace a deck load through hangers and main cables, then identify tower support and end-anchorage reactions. Add a separate thermal-movement arrow.","observation":"注意吊索大致垂直，而主纜曲線連續通過塔頂。","observationEn":"Notice the approximately vertical hangers and the main cable continuing over the towers.","failure":"把主纜當成從塔頂直接放射到橋面的斜張索。","failureEn":"Mistaking the main cable for separate stays radiating directly from a tower to the deck.","check":"載荷路徑須包含錨碇，且與伸縮箭頭使用不同圖例。","checkEn":"Include anchorages in the load path and distinguish force arrows from movement arrows.","knowledge":[{"id":"b003-v6-02-k1","title":"懸索與斜張","titleEn":"Suspension versus cable-stayed","text":"懸索橋以主纜與吊索承托橋面；斜張橋的斜索直接連結塔與梁。","textEn":"A suspension bridge supports its deck through main cables and hangers; stays connect a cable-stayed deck directly to towers."},{"id":"b003-v6-02-k2","title":"反力閉合","titleEn":"Reaction closure","text":"辨識拉力仍須追查由哪個支承或地盤提供平衡反力。","textEn":"Identifying tension also requires locating the support or ground that balances it."}],"quiz":{"options":["吊索到橋面的局部傳力已完整，所以不需其他反力","主纜端部拉力的反力路徑","主塔承受壓力即可代替所有端部反力"],"optionsEn":["Local hanger-to-deck transfer is complete, so no further reaction is needed","The reaction path for end cable tension","Tower compression can replace all end reactions"],"answer":1,"question":"如果示意圖刪掉主纜端部的錨碇，主要遺漏是什麼？","questionEn":"What is chiefly missing if a sketch omits the main-cable anchorages?","explanation":"錨碇是懸索系統的受力邊界，不能只畫橋面、塔和吊索。","explanationEn":"Anchorages define the suspension system’s force boundary; deck, towers and hangers alone are incomplete."}},{"id":"b003-v6-03","sequence":3,"order":3,"sourceIds":["v6-akashi-engineering","v6-akashi-maintenance"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b003-v6-02"],"title":"拆解海中基礎介面","titleEn":"Separate marine-foundation interfaces","objective":"辨識海床、基礎與橋塔交界各需什麼證據。","objectiveEn":"Identify evidence needed at seabed, foundation and tower interfaces.","instruction":"畫出海床剖面、基礎底面與塔座，列出承載、變形、海床變化三類問題。將施工定位紀錄與營運期海床觀測分成兩欄。","instructionEn":"Draw seabed, foundation base and tower seat. List bearing, deformation and bed-change questions, separating construction-position records from operational seabed observations.","observation":"觀察同一塔頂位移可能來自基礎轉動或塔本身變形。","observationEn":"Recognize that tower-top movement may result from foundation rotation or tower deformation.","failure":"把單一塔頂讀數直接認定為海床承載失效。","failureEn":"Treating one tower-top reading as proof of seabed bearing failure.","check":"為三類問題各指定一種觀察量，並寫明無法由它單獨判定的事項。","checkEn":"Assign one observable to each question and state what it cannot establish alone.","knowledge":[{"id":"b003-v6-03-k1","title":"支承條件","titleEn":"Support conditions","text":"基礎的受力與變形都會影響上部結構的邊界條件。","textEn":"Foundation forces and deformations both affect superstructure boundary conditions."},{"id":"b003-v6-03-k2","title":"分層量測","titleEn":"Measurements at multiple levels","text":"塔頂、塔座及地盤的相對量測有助於區分變形來源。","textEn":"Relative measurements at tower top, base and ground help distinguish deformation sources."}],"quiz":{"options":["只增加同一位置讀數次數，不核對支承","另一次未註記時間的塔頂照片","塔座位移與環境條件的同期紀錄"],"optionsEn":["Repeat readings at the same point without checking support","Another tower-top photograph with no timestamp","Concurrent tower-base displacement and environmental records"],"answer":2,"question":"塔頂偏移增加時，哪組補充資料最有助診斷？","questionEn":"Which additional data best helps diagnose increased tower-top displacement?","explanation":"同步的支承與環境紀錄可檢查不同假說，單點讀數不能定位原因。","explanationEn":"Synchronized support and environmental records test competing explanations; one reading cannot locate the cause."}},{"id":"b003-v6-04","sequence":4,"order":4,"sourceIds":["v6-akashi-overview","v6-akashi-maintenance"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b003-v6-03"],"title":"核對錨碇與纜索交接","titleEn":"Review anchorage–cable interfaces","objective":"將端部受力模型連結到幾何與耐久檢查。","objectiveEn":"Connect an end-force model to geometry and durability checks.","instruction":"自繪主纜進入錨碇的簡圖，標出拉力傳遞、可檢查空間與水分進入方向。把錨碇和橋塔基礎列成兩個不同構件。","instructionEn":"Sketch a main cable entering an anchorage; mark force transfer, inspection space and possible moisture entry. List the anchorage separately from the tower foundation.","observation":"檢查力能否從纜索一路追蹤到錨碇與地盤。","observationEn":"Check whether the force path can be followed continuously from cable to anchorage and ground.","failure":"以表面塗層完好推論整個錨碇內部都乾燥且健全。","failureEn":"Inferring a dry, sound anchorage interior solely from intact surface coating.","check":"交付受力圖與耐久疑問各一張，註明需要的內部證據。","checkEn":"Provide a force sketch and a durability-question sheet naming the necessary internal evidence.","knowledge":[{"id":"b003-v6-04-k1","title":"構件職責","titleEn":"Component roles","text":"主塔支承主纜，端部錨碇承接纜索端力；兩者不應混為一談。","textEn":"Towers support main cables while end anchorages resist end forces; these roles differ."},{"id":"b003-v6-04-k2","title":"可檢查性","titleEn":"Inspectability","text":"無法直接看見的介面，需要事先規劃可追溯的檢查方法。","textEn":"Hidden interfaces require planned, traceable inspection methods."}],"quiz":{"options":["有位置與日期的內部檢查及濕度紀錄","只增加外表面檢查，假定內部條件一致","以當日車流估算內部濕度"],"optionsEn":["Located, dated internal inspection and humidity records","Increase external inspection and assume the interior matches","Infer internal humidity from the day’s traffic"],"answer":0,"question":"哪項證據最能補足錨碇外觀照片的限制？","questionEn":"Which evidence best supplements external anchorage photographs?","explanation":"內部環境和檢查位置才直接對應隱蔽介面的疑問。","explanationEn":"Internal conditions and inspection locations directly address hidden-interface questions."}}],"title":"海峽與受力系統","titleEn":"Strait and structural system","description":"先把航道、地盤與懸索受力放在同一概念模型中。","descriptionEn":"Put navigation, ground conditions and suspension load paths in one conceptual model."},{"id":"b003-stage02","order":2,"steps":[{"id":"b003-v6-05","sequence":5,"order":1,"sourceIds":["v6-akashi-overview","v6-akashi-engineering"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b003-v6-04"],"title":"比較主纜形狀與載荷","titleEn":"Compare cable shape and loading","objective":"理解纜索幾何與張力不能分開指定。","objectiveEn":"Understand why cable geometry and tension cannot be specified independently.","instruction":"以鬆弛繩模型或自繪曲線比較兩種下垂程度，在圖上放入相同的示意橋面載荷。只作定性判讀，列出求數值時還缺的材料和邊界資料。","instructionEn":"Compare two cable sags using loose string or sketches under the same illustrative deck load. Keep conclusions qualitative and list missing material and boundary data for numerical analysis.","observation":"觀察曲線變平時，端部力的方向也改變。","observationEn":"Observe that flattening the cable changes the end-force direction.","failure":"把下垂量減少誤認為必然能降低所有纜索力。","failureEn":"Assuming reduced sag necessarily reduces every cable force.","check":"圖中保留相同載荷假設，並說明不能由外形直接求出張力。","checkEn":"Keep the load assumption identical and explain why shape alone cannot give tension.","knowledge":[{"id":"b003-v6-05-k1","title":"柔性纜索","titleEn":"Flexible cable","text":"纜索主要以拉力傳力，平衡形狀會隨載荷與支承位置改變。","textEn":"A cable primarily carries tension; its equilibrium shape depends on loading and support positions."},{"id":"b003-v6-05-k2","title":"模型限制","titleEn":"Model limits","text":"繩模型未重現鋼纜剛度、溫度與橋面剛性，只展示幾何關係。","textEn":"A string model illustrates geometry without reproducing steel-cable stiffness, temperature effects or deck rigidity."}],"quiz":{"options":["只控制圖上的跨度，允許載荷不同","載荷與支承條件的假設","只控制纜索材料，忽略支承位置"],"optionsEn":["Hold only drawn span constant while changing the load","Assumptions about loading and supports","Hold only cable material constant and ignore support positions"],"answer":1,"question":"想比較兩種垂度的受力，哪項必須先控制一致？","questionEn":"What should first be held consistent when comparing forces for two sags?","explanation":"在不同載荷或支承下看到的差異不能只歸因於垂度。","explanationEn":"Differences under changed loads or supports cannot be attributed to sag alone."}},{"id":"b003-v6-06","sequence":6,"order":2,"sourceIds":["v6-akashi-engineering"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b003-v6-05"],"title":"追蹤分段架設狀態","titleEn":"Track staged deck erection","objective":"區分施工中與完工後的平衡系統。","objectiveEn":"Distinguish construction-stage equilibrium from the completed system.","instruction":"把橋面分成六個示意區段，自選兩種安裝先後並逐格畫出已連接構件。每一格標記不平衡載荷與尚未形成的連續性，不安排真實吊裝。","instructionEn":"Divide the deck into six illustrative segments and sketch two assembly sequences. For each state mark unbalanced loads and missing continuity; do not plan an actual lift.","observation":"比較單側增加一段橋面時，主纜和鄰近吊索的受力路徑如何改變。","observationEn":"Compare load-path changes in the main cable and adjacent hangers when a segment is added on one side.","failure":"直接套用完工橋的支承與連續性來評估每個施工格。","failureEn":"Applying completed-bridge support and continuity assumptions to every construction state.","check":"選出一個最需要重新分析的中間狀態，說明理由與缺少資料。","checkEn":"Select an intermediate state needing renewed analysis and explain why and what data is missing.","knowledge":[{"id":"b003-v6-06-k1","title":"階段結構","titleEn":"Stage-dependent structure","text":"構件尚未連接時，完工後的載荷重分配途徑可能不存在。","textEn":"Load redistribution available after completion may not exist before components are connected."},{"id":"b003-v6-06-k2","title":"工序依賴","titleEn":"Sequence dependency","text":"幾何調整和構件接合的結果會成為下一階段的初始條件。","textEn":"Geometry adjustment and connection outcomes become initial conditions for the next stage."}],"quiz":{"options":["中間狀態可直接沿用完工載荷分配","每個中間狀態都必定比完工更安全","未完成結構的連接與載荷不同"],"optionsEn":["Intermediate states can use final load distribution unchanged","Every intermediate state is necessarily safer than completion","Connections and loads differ in an incomplete structure"],"answer":2,"question":"哪個理由最能說明需要施工階段分析？","questionEn":"What best explains the need for construction-stage analysis?","explanation":"需要檢查的是當時實際存在的結構系統，而非只看終態。","explanationEn":"The relevant structure is the one that exists at that stage, not only the final state."}},{"id":"b003-v6-07","sequence":7,"order":3,"sourceIds":["v6-akashi-engineering"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b003-v6-06"],"title":"重建地震後測量基準","titleEn":"Reconcile post-earthquake geometry","objective":"理解基準變動如何影響尚未製造的構件。","objectiveEn":"Understand how changed reference geometry affects unfabricated components.","instruction":"依 1995 年事件畫出「地震前控制點—震後復測—更新模型—複核構件」流程。用自設的小位移示例，分開記錄地盤移動與構件相對變形。","instructionEn":"Based on the 1995 event, map pre-event controls, resurvey, model update and component review. In a clearly invented displacement example, separate ground movement from relative component deformation.","observation":"比較兩塔間距變化與塔本身損傷是否是不同證據問題。","observationEn":"Distinguish a changed tower spacing from evidence of damage within a tower.","failure":"控制點移動後，仍把舊座標當成固定真值調整構件。","failureEn":"Adjusting components to old coordinates after the control points have moved.","check":"記錄示例新舊基準、相對距離與待重審構件，禁止把示例值當實測。","checkEn":"Record old and new references, relative distances and components needing review; label every example value as invented.","knowledge":[{"id":"b003-v6-07-k1","title":"共同位移","titleEn":"Common movement","text":"地盤與基礎共同移動，與基礎對地盤滑動，是不同的機制。","textEn":"Ground and foundation moving together differs from a foundation sliding relative to ground."},{"id":"b003-v6-07-k2","title":"版本追溯","titleEn":"Version traceability","text":"幾何基準修訂要能追溯到分析模型與待製構件版本。","textEn":"A revised geometric reference must be traceable to model and component versions."}],"quiz":{"options":["仍須復測並檢查模型與構件介面","外觀正常即可忽略幾何改變","立即判定所有基礎已滑動"],"optionsEn":["Resurvey and review model and component interfaces","Normal appearance makes geometry changes irrelevant","Conclude immediately that all foundations slid"],"answer":0,"question":"震後塔距改變，但構件外觀無明顯損傷，應如何解讀？","questionEn":"Tower spacing changes after an earthquake without visible member damage. What follows?","explanation":"外觀、相對位移與受力是不同證據層次，須整合後判斷。","explanationEn":"Appearance, relative displacement and force behavior are different evidence layers that must be reconciled."}},{"id":"b003-v6-08","sequence":8,"order":4,"sourceIds":["v6-akashi-engineering","v6-akashi-maintenance"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b003-v6-07"],"title":"分辨靜風與振動問題","titleEn":"Distinguish static wind and vibration","objective":"識別風力、變形與振動穩定性所需的不同模型。","objectiveEn":"Identify different models for wind force, deformation and dynamic stability.","instruction":"為靜態側向風力、渦激反應與扭轉振動各寫一個研究問題。以自繪位移—時間曲線比較衰減、持續與增長，避免賦予真實橋梁限值。","instructionEn":"Write separate questions about static crosswind force, vortex-induced response and torsional vibration. Sketch decaying, sustained and growing motion without assigning real-bridge limits.","observation":"觀察平均位移相近的曲線，振幅隨時間的變化仍可能不同。","observationEn":"Curves with similar mean displacement can have different amplitude trends over time.","failure":"只檢查最大靜態撓度，就宣稱已驗證所有風振現象。","failureEn":"Claiming all wind behavior is verified by checking maximum static deflection alone.","check":"將三種問題配對到合適的觀察量，標示定性曲線。","checkEn":"Match the three questions to suitable observables and label curves as qualitative.","knowledge":[{"id":"b003-v6-08-k1","title":"時間尺度","titleEn":"Time scale","text":"穩定平均風荷載與反覆振動需要不同的證據描述。","textEn":"Steady mean wind loading and repeated oscillation require different evidence descriptions."},{"id":"b003-v6-08-k2","title":"能量與阻尼","titleEn":"Energy and damping","text":"阻尼消散振動能量；它與單純提高靜態剛度的作用不同。","textEn":"Damping dissipates vibration energy, which differs from simply increasing static stiffness."}],"quiz":{"options":["圖上平均位移的方向","振幅是否隨時間增長","圖中使用的長度單位"],"optionsEn":["Direction of the plotted mean displacement","Whether vibration amplitude grows over time","Length units shown on the plot"],"answer":1,"question":"哪個現象無法由一張平均撓度圖充分判斷？","questionEn":"What cannot be adequately judged from a mean-deflection plot?","explanation":"振動增長需要時間或動態穩定性資訊；平均量會隱藏它。","explanationEn":"Growth requires time-dependent or stability information; averages can hide it."}}],"title":"架設與幾何控制","titleEn":"Erection and geometric control","description":"比較未完成結構的平衡、基準變更與風振假設。","descriptionEn":"Compare incomplete-structure equilibrium, changed survey references and wind-response assumptions."},{"id":"b003-stage03","order":3,"steps":[{"id":"b003-v6-09","sequence":9,"order":1,"sourceIds":["v6-akashi-maintenance"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b003-v6-08"],"title":"畫出主纜乾燥屏障","titleEn":"Map the cable drying barrier","objective":"說明外包覆與內部乾燥的互補關係。","objectiveEn":"Explain how wrapping and internal drying complement each other.","instruction":"自繪主纜包覆、送氣、排氣及濕度觀測點的功能圖。為「包覆局部進水」與「送氣中斷」各列一項可觀察證據，不指定設備參數。","instructionEn":"Sketch functional roles of cable wrapping, air supply, exhaust and humidity observations. For local water ingress and interrupted air supply, name evidence without specifying operating parameters.","observation":"檢查進氣正常是否仍可能與局部高濕並存。","observationEn":"Ask whether normal inlet air can coexist with a locally humid region.","failure":"以乾燥機正在運轉，取代主纜內部環境的證據。","failureEn":"Substituting evidence that a dryer is running for evidence about conditions inside the cable.","check":"圖上須有兩個不同失效路徑與對應觀察點。","checkEn":"Include two distinct failure paths and corresponding observation locations.","knowledge":[{"id":"b003-v6-09-k1","title":"防蝕多重屏障","titleEn":"Complementary corrosion barriers","text":"外包覆抑制水分進入，乾燥系統改善內部環境；兩者提供不同功能。","textEn":"Wrapping limits moisture entry while drying changes internal conditions; the functions differ."},{"id":"b003-v6-09-k2","title":"代表性採樣","titleEn":"Representative sampling","text":"一個位置的濕度，不能自動代表整條纜索的狀態。","textEn":"Humidity measured at one point does not automatically represent the entire cable."}],"quiz":{"options":["直接把遠端讀值刪除","用乾燥機功率證明全纜乾燥","核對量測與局部氣流或包覆異常"],"optionsEn":["Delete the distant reading","Use dryer power as proof the entire cable is dry","Check measurements and local airflow or wrapping anomalies"],"answer":2,"question":"送氣端讀值正常而遠端濕度偏高，最合理的下一步是什麼？","questionEn":"Inlet readings are normal but a distant point is humid. What is the best next review?","explanation":"不同位置的差異可能提供局部失效線索，須先查證。","explanationEn":"Differences between locations may reveal local failure and require verification."}},{"id":"b003-v6-10","sequence":10,"order":2,"sourceIds":["v6-akashi-maintenance"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b003-v6-09"],"title":"辨認重複載荷與接頭","titleEn":"Identify repeated loading at connections","objective":"區分疲勞、腐蝕與單次超載的證據。","objectiveEn":"Distinguish evidence of fatigue, corrosion and one-time overload.","instruction":"在自繪鋼橋面接頭示意上標記幾何變化處，建立三欄：反覆交通載荷、水分滯留、單次異常事件。為每欄列一種需要查證的紀錄。","instructionEn":"Mark geometric changes on a steel-deck connection sketch. Create columns for repeated traffic loading, trapped moisture and a single abnormal event, assigning evidence to each.","observation":"留意細小裂紋的位置及歷次變化，比單一遠景照片更具診斷性。","observationEn":"Crack location and change over time are more diagnostic than one distant photograph.","failure":"看到鏽色就把所有裂紋歸因於腐蝕，忽略載荷歷程。","failureEn":"Attributing every crack to corrosion because rust is visible, without considering load history.","check":"完成三種機制的證據表，至少列一項仍不能排除的替代解釋。","checkEn":"Complete the three-mechanism evidence table and retain at least one alternative explanation.","knowledge":[{"id":"b003-v6-10-k1","title":"局部細節","titleEn":"Local details","text":"幾何不連續可能集中應力；整體受力正常不保證每個接頭無問題。","textEn":"Geometric discontinuities can concentrate stress; normal global behavior does not prove every connection sound."},{"id":"b003-v6-10-k2","title":"機制辨識","titleEn":"Mechanism identification","text":"裂紋形態、環境與載荷歷程應一起判讀，不能只靠顏色。","textEn":"Crack form, environment and load history should be interpreted together rather than from color alone."}],"quiz":{"options":["同位置、同尺度的歷次量測","不同位置的裂紋照片但沒有時間對照","只記錄當日總車流，不核對裂紋位置"],"optionsEn":["Repeated measurements at the same location and scale","Crack photographs from different locations without time comparison","Record only daily traffic without locating the crack"],"answer":0,"question":"哪項資料最有助區分持續發展的裂紋與穩定表面痕跡？","questionEn":"Which data best distinguishes a developing crack from a stable surface mark?","explanation":"可比較的時間序列才提供變化證據；外觀單照缺少發展資訊。","explanationEn":"Comparable time-series observations provide change evidence that a single image lacks."}},{"id":"b003-v6-11","sequence":11,"order":3,"sourceIds":["v6-akashi-maintenance"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b003-v6-10"],"title":"校正監測比較條件","titleEn":"Normalize monitoring comparisons","objective":"避免把溫度或儀器差異誤認為結構劣化。","objectiveEn":"Avoid mistaking environmental or instrument differences for structural deterioration.","instruction":"自行製作含時間、溫度、風況、感測器和位移的六列示例表。選出可直接比較的兩列，再為其餘列註記需校正或補查的條件。","instructionEn":"Create a six-row example table with time, temperature, wind, sensor and displacement. Select two comparable rows and mark conditions requiring adjustment or investigation in the others.","observation":"觀察位移異常是否與換感測器或環境改變同時發生。","observationEn":"See whether displacement changes coincide with sensor replacement or environmental changes.","failure":"把不同零點或不同溫度的資料直接相減，產生假趨勢。","failureEn":"Direct subtraction across different zero references or temperatures creates a false trend.","check":"保留原始示例值、比較依據與未解釋的殘差，不覆寫原紀錄。","checkEn":"Retain original example values, comparison criteria and unexplained residuals without overwriting records.","knowledge":[{"id":"b003-v6-11-k1","title":"基線條件","titleEn":"Baseline conditions","text":"基線不只是單一數值，還包括量測時間、環境、設備與基準。","textEn":"A baseline includes time, environment, instrument and reference, not just one value."},{"id":"b003-v6-11-k2","title":"可重現性","titleEn":"Reproducibility","text":"他人應能利用相同選取規則重建你的比較結果。","textEn":"Another reviewer should reproduce the comparison using the same selection rules."}],"quiz":{"options":["直接宣告主纜斷裂","新舊感測器的零點和交接紀錄","把前後資料平均後忽略跳變"],"optionsEn":["Immediately declare main-cable rupture","Old and new sensor zero references and handover records","Average the records and disregard the jump"],"answer":1,"question":"更換感測器當天出現位移跳變，應優先核對什麼？","questionEn":"A displacement jump appears on the day a sensor is replaced. What should be checked first?","explanation":"先排查量測系統變動，再結合結構和環境證據判讀。","explanationEn":"Check measurement-system changes before interpreting structural and environmental evidence."}},{"id":"b003-v6-12","sequence":12,"order":4,"sourceIds":["v6-akashi-overview","v6-akashi-engineering","v6-akashi-maintenance"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b003-v6-11"],"title":"交付懸索橋證據卷宗","titleEn":"Deliver a suspension-bridge evidence dossier","objective":"把結構、施工與維護的未解問題交接清楚。","objectiveEn":"Clearly hand over unresolved structural, construction and maintenance questions.","instruction":"把前述圖表整理成索引：載荷路徑、基準版本、架設狀態、風振問題及纜索防蝕。對每份資料註明來源、假設與支持的判斷範圍。","instructionEn":"Index your load-path, reference-version, erection-state, wind-response and corrosion records. For each, identify source, assumptions and the conclusion it can support.","observation":"檢查是否把某一階段的分析誤用為整橋所有狀態的證明。","observationEn":"Check whether evidence for one stage has been mistaken for proof of every bridge state.","failure":"只交付漂亮模型，沒有資料版本、量測條件或待確認事項。","failureEn":"Delivering an attractive model without versions, measurement conditions or unresolved items.","check":"以「已支持／未支持／需專業複核」分類至少五項判斷。","checkEn":"Classify at least five conclusions as supported, unsupported or requiring professional review.","knowledge":[{"id":"b003-v6-12-k1","title":"證據對應","titleEn":"Evidence matching","text":"每項結論需對應適用狀態與資料，不能用一張圖概括全生命週期。","textEn":"Each conclusion requires applicable conditions and evidence; one sketch cannot cover an entire life cycle."},{"id":"b003-v6-12-k2","title":"教育交付","titleEn":"Educational deliverable","text":"課程完成代表學習證據齊備，不等於取得真橋施工或通行安全認證。","textEn":"Course completion records learning evidence, not construction or operational safety certification for the real bridge."}],"quiz":{"options":["只保留沒有圖例的完工圖像","刪除所有不確定事項以顯得完整","含來源版本、假設與未解問題的索引"],"optionsEn":["Only a finished image without a key","Delete uncertainties to make the work look complete","An index with source versions, assumptions and open questions"],"answer":2,"question":"哪份交付最適合另一位工程學徒接續？","questionEn":"Which handover best enables another learner to continue?","explanation":"可追溯性使下一位能看出已知與未知，避免把示意當定案。","explanationEn":"Traceability distinguishes known from unknown and prevents treating a sketch as an approved design."}}],"title":"耐久與營運證據","titleEn":"Durability and operating evidence","description":"把纜索、鋼構與感測紀錄連結到可追溯的維護判斷。","descriptionEn":"Connect cable, steelwork and sensor records to traceable maintenance decisions."},{"id":"b003-v13-s1","title":"工程背景、荷載與結構系統","titleEn":"Context, loads and structural system","description":"本階段聚焦「桁架加勁梁的顫振臨界風速」與「長週期模態與地震輸入」：先建立傳力機制與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Flutter onset of the truss stiffening girder\" and \"Long-period modes and seismic input\": build the load path and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b003-v13-01","title":"桁架加勁梁的顫振臨界風速：機制與傳力路徑","titleEn":"Flutter onset of the truss stiffening girder: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v6-12"],"objective":"說明「桁架加勁梁顫振裕度」如何影響明石海峽大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “Truss flutter margin” governs force, deformation or durability in “Akashi Kaikyo Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"主跨接近 2 km 時，加勁梁的扭轉頻率與豎彎頻率都很低，風在某一速度下會讓兩者耦合成自激的顫振：氣動力隨扭轉角輸入能量，總阻尼由正轉負，振幅在數個週期內發散。明石海峽大橋採用約 35.5 m 寬、14 m 深的開放式鋼桁架，橋面設置格柵開口與中央垂直穩定板，目的是打亂橋面上下的壓力差、提高顫振臨界風速。桁架斷面的氣動導數與流線形箱梁差異很大，只能靠斷面模型與全橋模型試驗確定。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「桁架加勁梁顫振裕度」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"When the main span approaches 2 km, both the torsional and the vertical bending frequencies of the stiffening girder are very low, and at some wind speed the two couple into self-excited flutter: aerodynamic forces feed energy through the twist angle, total damping turns negative and the amplitude diverges within a few cycles. Akashi Kaikyo uses an open steel truss about 35.5 m wide and 14 m deep, with gratings in the deck and a central vertical stabiliser, to disrupt the pressure difference across the deck and raise the flutter onset speed. The aerodynamic derivatives of a truss differ greatly from those of a streamlined box, so they can only be fixed by section-model and full-bridge model tests. Mentor task: draw a free-body or load-path diagram showing how loads pass through “Truss flutter margin” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：Selberg 平板估算 U_F = 0.44·B·ω_T·√[(1 − (f_B/f_T)²)·√(m·I)/(ρB³)]。","observationEn":"Order-of-magnitude cue: Selberg flat-plate estimate U_F = 0.44·B·ω_T·√[(1 − (f_B/f_T)²)·√(m·I)/(ρB³)].","failure":"常見誤解：「桁架加勁梁很深很重，所以不會發生顫振。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A truss stiffening girder is deep and heavy, so it cannot flutter.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「桁架加勁梁顫振裕度」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “Truss flutter margin”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b003-v13-01-k1","title":"桁架加勁梁的顫振臨界風速","titleEn":"Flutter onset of the truss stiffening girder","text":"主跨接近 2 km 時，加勁梁的扭轉頻率與豎彎頻率都很低，風在某一速度下會讓兩者耦合成自激的顫振：氣動力隨扭轉角輸入能量，總阻尼由正轉負，振幅在數個週期內發散。明石海峽大橋採用約 35.5 m 寬、14 m 深的開放式鋼桁架，橋面設置格柵開口與中央垂直穩定板，目的是打亂橋面上下的壓力差、提高顫振臨界風速。","textEn":"When the main span approaches 2 km, both the torsional and the vertical bending frequencies of the stiffening girder are very low, and at some wind speed the two couple into self-excited flutter: aerodynamic forces feed energy through the twist angle, total damping turns negative and the amplitude diverges within a few cycles. Akashi Kaikyo uses an open steel truss about 35.5 m wide and 14 m deep, with gratings in the deck and a central vertical stabiliser, to disrupt the pressure difference across the deck and raise the flutter onset speed.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：桁架加勁梁很深很重，所以不會發生顫振。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A truss stiffening girder is deep and heavy, so it cannot flutter. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"關於「桁架加勁梁的顫振臨界風速」，下列哪一項敘述正確？","questionEn":"Which statement about \"Flutter onset of the truss stiffening girder\" is correct?","options":["桁架加勁梁很深很重，所以不會發生顫振。","主跨接近 2 km 時，加勁梁的扭轉頻率與豎彎頻率都很低，風在某一速度下會讓兩者耦合成自激的顫振：氣動力隨扭轉角輸入能量，總阻尼由正轉負，振幅在數個週期內發散。","懸索橋很柔，所以地震對它幾乎沒有影響。"],"optionsEn":["A truss stiffening girder is deep and heavy, so it cannot flutter.","When the main span approaches 2 km, both the torsional and the vertical bending frequencies of the stiffening girder are very low, and at some wind speed the two couple into self-excited flutter: aerodynamic forces feed energy through the twist angle, total damping turns negative and the amplitude diverges within a few cycles.","A suspension bridge is so flexible that earthquakes hardly affect it."],"answer":1,"explanation":"主跨接近 2 km 時，加勁梁的扭轉頻率與豎彎頻率都很低，風在某一速度下會讓兩者耦合成自激的顫振：氣動力隨扭轉角輸入能量，總阻尼由正轉負，振幅在數個週期內發散。 其餘選項是常見誤解。","explanationEn":"When the main span approaches 2 km, both the torsional and the vertical bending frequencies of the stiffening girder are very low, and at some wind speed the two couple into self-excited flutter: aerodynamic forces feed energy through the twist angle, total damping turns negative and the amplitude diverges within a few cycles. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":13},{"id":"b003-v13-02","title":"桁架加勁梁的顫振臨界風速：定量估算","titleEn":"Flutter onset of the truss stiffening girder: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-01"],"objective":"以數值模型估算「桁架加勁梁顫振裕度」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Truss flutter margin” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：Selberg 平板估算 U_F = 0.44·B·ω_T·√[(1 − (f_B/f_T)²)·√(m·I)/(ρB³)]。取 B = 35.5 m、m = 44,000 kg/m、I = 6.0×10⁶ kg·m²/m、f_B = 0.065 Hz、f_T = 0.16 Hz、ρ = 1.25 kg/m³：ω_T = 1.005 rad/s，√(m·I)/(ρB³) = 513,800/55,920 = 9.19，U_F = 0.44×35.5×1.005×√(0.835×9.19) ≈ 43 m/s；f_T 提高到 0.18 Hz 時約 50 m/s。數值為教學假設，平板公式對桁架只作量級比較。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Selberg flat-plate estimate U_F = 0.44·B·ω_T·√[(1 − (f_B/f_T)²)·√(m·I)/(ρB³)]. With B = 35.5 m, m = 44,000 kg/m, I = 6.0×10⁶ kg·m²/m, f_B = 0.065 Hz, f_T = 0.16 Hz and ρ = 1.25 kg/m³: ω_T = 1.005 rad/s, √(m·I)/(ρB³) = 513,800/55,920 = 9.19, so U_F = 0.44×35.5×1.005×√(0.835×9.19) ≈ 43 m/s; raising f_T to 0.18 Hz gives about 50 m/s. Values are teaching assumptions; for a truss the flat-plate formula only gives an order of magnitude. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以斷面模型強迫振動試驗量測 Scanlan 氣動導數 H*、A*，代入多模態顫振分析求臨界風速，再與全橋氣彈模型在紊流中的發散風速比較；驗收以顫振臨界風速高於規範的照查風速（設計風速乘陣風與安全係數）為準，並檢查不同風攻角（例如 ±3°）下的最低值。","observationEn":"How to cross-check: Measure Scanlan aerodynamic derivatives H* and A* with forced-oscillation section-model tests, feed them into a multi-mode flutter analysis, and compare the predicted onset speed with the divergence speed of a full aeroelastic model in turbulent flow; acceptance requires the flutter onset to exceed the code verification speed (design wind times gust and safety factors), checking the lowest value over angles of attack such as ±3°.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b003-v13-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"Selberg 平板估算 U_F = 0.44·B·ω_T·√[(1 − (f_B/f_T)²)·√(m·I)/(ρB³)]。取 B = 35.5 m、m = 44,000 kg/m、I = 6.0×10⁶ kg·m²/m、f_B = 0.065 Hz、f_T = 0.16 Hz、ρ = 1.25 kg/m³：ω_T = 1.005 rad/s，√(m·I)/(ρB³) = 513,800/55,920 = 9.19，U_F = 0.44×35.5×1.005×√(0.835×9.19) ≈ 43 m/s；f_T 提高到 0.18 Hz 時約 50 m/s。數值為教學假設，平板公式對桁架只作量級比較。","textEn":"Selberg flat-plate estimate U_F = 0.44·B·ω_T·√[(1 − (f_B/f_T)²)·√(m·I)/(ρB³)]. With B = 35.5 m, m = 44,000 kg/m, I = 6.0×10⁶ kg·m²/m, f_B = 0.065 Hz, f_T = 0.16 Hz and ρ = 1.25 kg/m³: ω_T = 1.005 rad/s, √(m·I)/(ρB³) = 513,800/55,920 = 9.19, so U_F = 0.44×35.5×1.005×√(0.835×9.19) ≈ 43 m/s; raising f_T to 0.18 Hz gives about 50 m/s. Values are teaching assumptions; for a truss the flat-plate formula only gives an order of magnitude.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"依「桁架加勁梁的顫振臨界風速」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Flutter onset of the truss stiffening girder\", which statement holds?","options":["水中混凝土只要配比強度夠高，澆置方式不影響品質。","地震後只要把橋塔推回原位，就能維持原設計線形。","Selberg 平板估算 U_F = 0.44·B·ω_T·√[(1 − (f_B/f_T)²)·√(m·I)/(ρB³)]。"],"optionsEn":["If the underwater mix is strong enough, the placing method does not affect quality.","After an earthquake you simply push the towers back to restore the design profile.","Selberg flat-plate estimate U_F = 0.44·B·ω_T·√[(1 − (f_B/f_T)²)·√(m·I)/(ρB³)]."],"answer":2,"explanation":"Selberg 平板估算 U_F = 0.44·B·ω_T·√[(1 − (f_B/f_T)²)·√(m·I)/(ρB³)]。 重算時請保留單位。","explanationEn":"Selberg flat-plate estimate U_F = 0.44·B·ω_T·√[(1 − (f_B/f_T)²)·√(m·I)/(ρB³)]. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":14},{"id":"b003-v13-03","title":"桁架加勁梁的顫振臨界風速：試驗與驗證","titleEn":"Flutter onset of the truss stiffening girder: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「桁架加勁梁顫振裕度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Truss flutter margin” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以斷面模型強迫振動試驗量測 Scanlan 氣動導數 H*、A*，代入多模態顫振分析求臨界風速，再與全橋氣彈模型在紊流中的發散風速比較；驗收以顫振臨界風速高於規範的照查風速（設計風速乘陣風與安全係數）為準，並檢查不同風攻角（例如 ±3°）下的最低值。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure Scanlan aerodynamic derivatives H* and A* with forced-oscillation section-model tests, feed them into a multi-mode flutter analysis, and compare the predicted onset speed with the divergence speed of a full aeroelastic model in turbulent flow; acceptance requires the flutter onset to exceed the code verification speed (design wind times gust and safety factors), checking the lowest value over angles of attack such as ±3°. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：任何在加勁桁架上新增的檢修走道、管線或防護網，都要先由風工程師評估對格柵開孔率與穩定板的影響，必要時補做斷面模型試驗；維護計畫須把格柵清潔列為定期項目。","observationEn":"Site practice: Any walkway, duct or screen added to the stiffening truss must first be assessed by the wind engineer for its effect on grating porosity and the stabiliser, with a new section-model test if needed; the maintenance plan must list grating cleaning as a routine item.","failure":"注意干擾：若沿用平板或箱梁的經驗值而未針對桁架做試驗，可能高估臨界風速；顫振一旦發生，扭轉振幅在數分鐘內增長，1940 年塔科馬海峽橋就是以扭轉發散破壞。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Borrowing flat-plate or box-girder values without testing the truss can overestimate the onset speed; once flutter starts, torsional amplitude grows within minutes, as in the torsional collapse of the Tacoma Narrows Bridge in 1940. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b003-v13-03-k1","title":"驗證方法","titleEn":"Verification method","text":"以斷面模型強迫振動試驗量測 Scanlan 氣動導數 H*、A*，代入多模態顫振分析求臨界風速，再與全橋氣彈模型在紊流中的發散風速比較；驗收以顫振臨界風速高於規範的照查風速（設計風速乘陣風與安全係數）為準，並檢查不同風攻角（例如 ±3°）下的最低值。","textEn":"Measure Scanlan aerodynamic derivatives H* and A* with forced-oscillation section-model tests, feed them into a multi-mode flutter analysis, and compare the predicted onset speed with the divergence speed of a full aeroelastic model in turbulent flow; acceptance requires the flutter onset to exceed the code verification speed (design wind times gust and safety factors), checking the lowest value over angles of attack such as ±3°.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-03-k2","title":"現場實務","titleEn":"Site practice","text":"任何在加勁桁架上新增的檢修走道、管線或防護網，都要先由風工程師評估對格柵開孔率與穩定板的影響，必要時補做斷面模型試驗；維護計畫須把格柵清潔列為定期項目。","textEn":"Any walkway, duct or screen added to the stiffening truss must first be assessed by the wind engineer for its effect on grating porosity and the stabiliser, with a new section-model test if needed; the maintenance plan must list grating cleaning as a routine item.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"要驗證「桁架加勁梁的顫振臨界風速」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Flutter onset of the truss stiffening girder\"?","options":["以斷面模型強迫振動試驗量測 Scanlan 氣動導數 H*、A*，代入多模態顫振分析求臨界風速，再與全橋氣彈模型在紊流中的發散風速比較。","量測時不必記錄溫度、日照、風與施工荷重，因為它們不會影響結果。","只要吊索間距大於 5 倍直徑，就不會有尾流振動。"],"optionsEn":["Measure Scanlan aerodynamic derivatives H* and A* with forced-oscillation section-model tests, feed them into a multi-mode flutter analysis, and compare the predicted onset speed with the divergence speed of a full aeroelastic model in turbulent flow.","Temperature, sunshine, wind and construction loads need not be recorded because they cannot affect the result.","Hangers spaced more than five diameters apart can never suffer wake vibration."],"answer":0,"explanation":"以斷面模型強迫振動試驗量測 Scanlan 氣動導數 H*、A*，代入多模態顫振分析求臨界風速，再與全橋氣彈模型在紊流中的發散風速比較；驗收以顫振臨界風速高於規範的照查風速（設計風速乘陣風與安全係數）為準，並檢查不同風攻角（例如 ±3°）下的最低值。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure Scanlan aerodynamic derivatives H* and A* with forced-oscillation section-model tests, feed them into a multi-mode flutter analysis, and compare the predicted onset speed with the divergence speed of a full aeroelastic model in turbulent flow; acceptance requires the flutter onset to exceed the code verification speed (design wind times gust and safety factors), checking the lowest value over angles of attack such as ±3°. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":15},{"id":"b003-v13-04","title":"桁架加勁梁的顫振臨界風速：失效診斷","titleEn":"Flutter onset of the truss stiffening girder: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-03"],"objective":"從症狀倒推「桁架加勁梁顫振裕度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Truss flutter margin” and propose discriminating checks, corrective actions and prevention.","instruction":"若沿用平板或箱梁的經驗值而未針對桁架做試驗，可能高估臨界風速；顫振一旦發生，扭轉振幅在數分鐘內增長，1940 年塔科馬海峽橋就是以扭轉發散破壞。格柵被雜物或後加設備堵塞，也會讓實橋氣動特性偏離試驗斷面。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Borrowing flat-plate or box-girder values without testing the truss can overestimate the onset speed; once flutter starts, torsional amplitude grows within minutes, as in the torsional collapse of the Tacoma Narrows Bridge in 1940. Gratings blocked by debris or later-added equipment also move the real deck away from the tested section. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：桁架斷面的氣動導數與流線形箱梁差異很大，只能靠斷面模型與全橋模型試驗確定。","observationEn":"Link to the mechanism: The aerodynamic derivatives of a truss differ greatly from those of a streamlined box, so they can only be fixed by section-model and full-bridge model tests.","failure":"誤判風險：若相信「桁架加勁梁很深很重，所以不會發生顫振。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A truss stiffening girder is deep and heavy, so it cannot flutter.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b003-v13-04-k1","title":"失效模式","titleEn":"Failure mode","text":"若沿用平板或箱梁的經驗值而未針對桁架做試驗，可能高估臨界風速；顫振一旦發生，扭轉振幅在數分鐘內增長，1940 年塔科馬海峽橋就是以扭轉發散破壞。格柵被雜物或後加設備堵塞，也會讓實橋氣動特性偏離試驗斷面。","textEn":"Borrowing flat-plate or box-girder values without testing the truss can overestimate the onset speed; once flutter starts, torsional amplitude grows within minutes, as in the torsional collapse of the Tacoma Narrows Bridge in 1940. Gratings blocked by debris or later-added equipment also move the real deck away from the tested section.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"在「桁架加勁梁的顫振臨界風速」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Flutter onset of the truss stiffening girder\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","若沿用平板或箱梁的經驗值而未針對桁架做試驗，可能高估臨界風速；顫振一旦發生，扭轉振幅在數分鐘內增長，1940 年塔科馬海峽橋就是以扭轉發散破壞。","懸索橋很柔，所以地震對它幾乎沒有影響。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Borrowing flat-plate or box-girder values without testing the truss can overestimate the onset speed.","A suspension bridge is so flexible that earthquakes hardly affect it."],"answer":1,"explanation":"若沿用平板或箱梁的經驗值而未針對桁架做試驗，可能高估臨界風速；顫振一旦發生，扭轉振幅在數分鐘內增長，1940 年塔科馬海峽橋就是以扭轉發散破壞。 需以量測區分可能原因。","explanationEn":"Borrowing flat-plate or box-girder values without testing the truss can overestimate the onset speed; once flutter starts, torsional amplitude grows within minutes, as in the torsional collapse of the Tacoma Narrows Bridge in 1940. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":16},{"id":"b003-v13-05","title":"長週期模態與地震輸入：機制與傳力路徑","titleEn":"Long-period modes and seismic input: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-04"],"objective":"說明「長週期豎彎模態」如何影響明石海峽大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “Long-period vertical modes” governs force, deformation or durability in “Akashi Kaikyo Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"懸索橋的豎向勁度主要來自主纜的重力張力，而不是加勁梁的彎曲勁度，因此低階模態週期可長達十秒以上，像一條張緊的弦。這使主跨對短週期地震加速度不敏感，卻對長週期地震波、海峽地盤的大變位與基礎間的相對位移很敏感。明石海峽大橋的耐震設計考慮規模 8.5 級的板塊交界地震，並把基礎設在避開活動斷層的位置；但 1995 年兵庫縣南部地震的斷層錯動仍使地盤與基礎一起移動，提醒設計者：相對位移與絕對加速度是兩個不同的設計問題。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「長週期豎彎模態」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"The vertical stiffness of a suspension bridge comes mainly from the gravity tension in its main cables rather than the bending stiffness of the stiffening girder, so the lowest modes can have periods of more than ten seconds, like a taut string. The main span is therefore insensitive to short-period ground acceleration but sensitive to long-period waves, large ground displacement in the strait and relative movement between foundations. The Akashi Kaikyo design considered a magnitude 8.5 interplate earthquake and sited foundations away from active faults, yet in the 1995 Hyogo-ken Nanbu earthquake fault movement still carried the ground and foundations together, a reminder that relative displacement and absolute acceleration are two separate design problems. Mentor task: draw a free-body or load-path diagram showing how loads pass through “Long-period vertical modes” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：以弦近似，反對稱第一豎彎頻率 f ≈ (1/l)·√(H/m)。","observationEn":"Order-of-magnitude cue: In the string approximation the first antisymmetric vertical frequency is f ≈ (1/l)·√(H/m).","failure":"常見誤解：「懸索橋很柔，所以地震對它幾乎沒有影響。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A suspension bridge is so flexible that earthquakes hardly affect it.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「長週期豎彎模態」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “Long-period vertical modes”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b003-v13-05-k1","title":"長週期模態與地震輸入","titleEn":"Long-period modes and seismic input","text":"懸索橋的豎向勁度主要來自主纜的重力張力，而不是加勁梁的彎曲勁度，因此低階模態週期可長達十秒以上，像一條張緊的弦。這使主跨對短週期地震加速度不敏感，卻對長週期地震波、海峽地盤的大變位與基礎間的相對位移很敏感。","textEn":"The vertical stiffness of a suspension bridge comes mainly from the gravity tension in its main cables rather than the bending stiffness of the stiffening girder, so the lowest modes can have periods of more than ten seconds, like a taut string. The main span is therefore insensitive to short-period ground acceleration but sensitive to long-period waves, large ground displacement in the strait and relative movement between foundations.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：懸索橋很柔，所以地震對它幾乎沒有影響。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A suspension bridge is so flexible that earthquakes hardly affect it. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"關於「長週期模態與地震輸入」，下列哪一項敘述正確？","questionEn":"Which statement about \"Long-period modes and seismic input\" is correct?","options":["懸索橋很柔，所以地震對它幾乎沒有影響。","鋼絲強度越高，主纜就越不需要防蝕。","懸索橋的豎向勁度主要來自主纜的重力張力，而不是加勁梁的彎曲勁度，因此低階模態週期可長達十秒以上，像一條張緊的弦。"],"optionsEn":["A suspension bridge is so flexible that earthquakes hardly affect it.","The stronger the wire, the less corrosion protection the cable needs.","The vertical stiffness of a suspension bridge comes mainly from the gravity tension in its main cables rather than the bending stiffness of the stiffening girder, so the lowest modes can have periods of more than ten seconds, like a taut string."],"answer":2,"explanation":"懸索橋的豎向勁度主要來自主纜的重力張力，而不是加勁梁的彎曲勁度，因此低階模態週期可長達十秒以上，像一條張緊的弦。 其餘選項是常見誤解。","explanationEn":"The vertical stiffness of a suspension bridge comes mainly from the gravity tension in its main cables rather than the bending stiffness of the stiffening girder, so the lowest modes can have periods of more than ten seconds, like a taut string. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":17},{"id":"b003-v13-06","title":"長週期模態與地震輸入：定量估算","titleEn":"Long-period modes and seismic input: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-05"],"objective":"以數值模型估算「長週期豎彎模態」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Long-period vertical modes” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：以弦近似，反對稱第一豎彎頻率 f ≈ (1/l)·√(H/m)。取兩纜合計 H = 1,074 MN、m = 44,000 kg/m、l = 1,991 m：√(1.074×10⁹/44,000) = 156 m/s，f ≈ 156/1,991 = 0.078 Hz，週期約 12.7 s。若 m 增加 10%，週期增為約 13.4 s。數值為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: In the string approximation the first antisymmetric vertical frequency is f ≈ (1/l)·√(H/m). With H = 1,074 MN for both cables, m = 44,000 kg/m and l = 1,991 m: √(1.074×10⁹/44,000) = 156 m/s, f ≈ 156/1,991 = 0.078 Hz and the period is about 12.7 s. A 10% increase in m lengthens the period to about 13.4 s. Values are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：把手算弦頻率與有限元素模態分析比較，確認前幾個模態的形狀（對稱、反對稱、側向、扭轉）與排序；耐震檢核需同時輸入長週期設計波與各基礎不同步的地盤位移，並把塔頂、索鞍與伸縮縫的相對位移與容許值逐一比對。","observationEn":"How to cross-check: Compare the hand string frequency with finite-element modal analysis, confirming the shape and order of the first modes (symmetric, antisymmetric, lateral, torsional); seismic checks must input long-period design motions and non-synchronous ground displacement at each foundation, comparing relative displacement at tower tops, saddles and expansion joints with their allowances.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b003-v13-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"以弦近似，反對稱第一豎彎頻率 f ≈ (1/l)·√(H/m)。取兩纜合計 H = 1,074 MN、m = 44,000 kg/m、l = 1,991 m：√(1.074×10⁹/44,000) = 156 m/s，f ≈ 156/1,991 = 0.078 Hz，週期約 12.7 s。若 m 增加 10%，週期增為約 13.4 s。數值為教學假設。","textEn":"In the string approximation the first antisymmetric vertical frequency is f ≈ (1/l)·√(H/m). With H = 1,074 MN for both cables, m = 44,000 kg/m and l = 1,991 m: √(1.074×10⁹/44,000) = 156 m/s, f ≈ 156/1,991 = 0.078 Hz and the period is about 12.7 s. A 10% increase in m lengthens the period to about 13.4 s. Values are teaching assumptions.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"依「長週期模態與地震輸入」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Long-period modes and seismic input\", which statement holds?","options":["以弦近似，反對稱第一豎彎頻率 f ≈ (1/l)·√(H/m)。","索股垂度只要白天量一次，誤差幾公分不影響主纜受力。","全橋模型的風速必須和實橋一樣，試驗才有意義。"],"optionsEn":["In the string approximation the first antisymmetric vertical frequency is f ≈ (1/l)·√(H/m).","Measuring strand sag once in daytime is fine; a few centimetres of error do not affect cable forces.","A full-bridge model is only meaningful if tested at the same wind speed as the real bridge."],"answer":0,"explanation":"以弦近似，反對稱第一豎彎頻率 f ≈ (1/l)·√(H/m)。 重算時請保留單位。","explanationEn":"In the string approximation the first antisymmetric vertical frequency is f ≈ (1/l)·√(H/m). Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":18},{"id":"b003-v13-07","title":"長週期模態與地震輸入：試驗與驗證","titleEn":"Long-period modes and seismic input: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「長週期豎彎模態」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Long-period vertical modes” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"把手算弦頻率與有限元素模態分析比較，確認前幾個模態的形狀（對稱、反對稱、側向、扭轉）與排序；耐震檢核需同時輸入長週期設計波與各基礎不同步的地盤位移，並把塔頂、索鞍與伸縮縫的相對位移與容許值逐一比對。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare the hand string frequency with finite-element modal analysis, confirming the shape and order of the first modes (symmetric, antisymmetric, lateral, torsional); seismic checks must input long-period design motions and non-synchronous ground displacement at each foundation, comparing relative displacement at tower tops, saddles and expansion joints with their allowances. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：耐震設計書應列出各基礎的地盤位移假設與斷層位置圖，並把相對位移需求寫進伸縮縫、支承與索鞍的採購規格；完工後的模態實測要回饋修正模型，作為日後事件評估的基準。","observationEn":"Site practice: The seismic design report should list ground-displacement assumptions for each foundation with a fault-location map, and write the relative-displacement demand into expansion-joint, bearing and saddle specifications; measured modes after completion must update the model as the baseline for future event assessments.","failure":"注意干擾：只用單一同步地震波分析時，會低估塔與錨碇之間的相對位移，伸縮縫、支承與索鞍可能超出行程；長週期波若與主跨低階模態接近，加勁梁位移可能遠大於以加速度反應譜估算的結果。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Analysing with a single synchronous record underestimates relative movement between towers and anchorages, so expansion joints, bearings and saddles may exceed their travel; long-period waves near the low modes of the main span can produce girder displacements far larger than an acceleration-spectrum estimate. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b003-v13-07-k1","title":"驗證方法","titleEn":"Verification method","text":"把手算弦頻率與有限元素模態分析比較，確認前幾個模態的形狀（對稱、反對稱、側向、扭轉）與排序；耐震檢核需同時輸入長週期設計波與各基礎不同步的地盤位移，並把塔頂、索鞍與伸縮縫的相對位移與容許值逐一比對。","textEn":"Compare the hand string frequency with finite-element modal analysis, confirming the shape and order of the first modes (symmetric, antisymmetric, lateral, torsional); seismic checks must input long-period design motions and non-synchronous ground displacement at each foundation, comparing relative displacement at tower tops, saddles and expansion joints with their allowances.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-07-k2","title":"現場實務","titleEn":"Site practice","text":"耐震設計書應列出各基礎的地盤位移假設與斷層位置圖，並把相對位移需求寫進伸縮縫、支承與索鞍的採購規格；完工後的模態實測要回饋修正模型，作為日後事件評估的基準。","textEn":"The seismic design report should list ground-displacement assumptions for each foundation with a fault-location map, and write the relative-displacement demand into expansion-joint, bearing and saddle specifications; measured modes after completion must update the model as the baseline for future event assessments.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"要驗證「長週期模態與地震輸入」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Long-period modes and seismic input\"?","options":["沿用另一座橋或另一棟建築的量測結果，就可視為本工程已完成驗證。","把手算弦頻率與有限元素模態分析比較，確認前幾個模態的形狀（對稱、反對稱、側向、扭轉）與排序。","主纜外面有鍍鋅纏絲與塗裝，內部就不會潮濕。"],"optionsEn":["Reusing results from another bridge or building counts as verifying this structure.","Compare the hand string frequency with finite-element modal analysis, confirming the shape and order of the first modes (symmetric, antisymmetric, lateral, torsional).","With galvanised wrapping and paint outside, the cable interior cannot get wet."],"answer":1,"explanation":"把手算弦頻率與有限元素模態分析比較，確認前幾個模態的形狀（對稱、反對稱、側向、扭轉）與排序；耐震檢核需同時輸入長週期設計波與各基礎不同步的地盤位移，並把塔頂、索鞍與伸縮縫的相對位移與容許值逐一比對。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare the hand string frequency with finite-element modal analysis, confirming the shape and order of the first modes (symmetric, antisymmetric, lateral, torsional); seismic checks must input long-period design motions and non-synchronous ground displacement at each foundation, comparing relative displacement at tower tops, saddles and expansion joints with their allowances. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":19},{"id":"b003-v13-08","title":"長週期模態與地震輸入：失效診斷","titleEn":"Long-period modes and seismic input: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-07"],"objective":"從症狀倒推「長週期豎彎模態」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Long-period vertical modes” and propose discriminating checks, corrective actions and prevention.","instruction":"只用單一同步地震波分析時，會低估塔與錨碇之間的相對位移，伸縮縫、支承與索鞍可能超出行程；長週期波若與主跨低階模態接近，加勁梁位移可能遠大於以加速度反應譜估算的結果。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Analysing with a single synchronous record underestimates relative movement between towers and anchorages, so expansion joints, bearings and saddles may exceed their travel; long-period waves near the low modes of the main span can produce girder displacements far larger than an acceleration-spectrum estimate. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：明石海峽大橋的耐震設計考慮規模 8.5 級的板塊交界地震，並把基礎設在避開活動斷層的位置；但 1995 年兵庫縣南部地震的斷層錯動仍使地盤與基礎一起移動，提醒設計者：相對位移與絕對加速度是兩個不同的設計問題。","observationEn":"Link to the mechanism: The Akashi Kaikyo design considered a magnitude 8.5 interplate earthquake and sited foundations away from active faults, yet in the 1995 Hyogo-ken Nanbu earthquake fault movement still carried the ground and foundations together, a reminder that relative displacement and absolute acceleration are two separate design problems.","failure":"誤判風險：若相信「懸索橋很柔，所以地震對它幾乎沒有影響。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A suspension bridge is so flexible that earthquakes hardly affect it.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b003-v13-08-k1","title":"失效模式","titleEn":"Failure mode","text":"只用單一同步地震波分析時，會低估塔與錨碇之間的相對位移，伸縮縫、支承與索鞍可能超出行程；長週期波若與主跨低階模態接近，加勁梁位移可能遠大於以加速度反應譜估算的結果。","textEn":"Analysing with a single synchronous record underestimates relative movement between towers and anchorages, so expansion joints, bearings and saddles may exceed their travel; long-period waves near the low modes of the main span can produce girder displacements far larger than an acceleration-spectrum estimate.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"在「長週期模態與地震輸入」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Long-period modes and seismic input\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","鋼絲強度越高，主纜就越不需要防蝕。","只用單一同步地震波分析時，會低估塔與錨碇之間的相對位移，伸縮縫、支承與索鞍可能超出行程。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","The stronger the wire, the less corrosion protection the cable needs.","Analysing with a single synchronous record underestimates relative movement between towers and anchorages, so expansion joints, bearings and saddles may exceed their travel."],"answer":2,"explanation":"只用單一同步地震波分析時，會低估塔與錨碇之間的相對位移，伸縮縫、支承與索鞍可能超出行程；長週期波若與主跨低階模態接近，加勁梁位移可能遠大於以加速度反應譜估算的結果。 需以量測區分可能原因。","explanationEn":"Analysing with a single synchronous record underestimates relative movement between towers and anchorages, so expansion joints, bearings and saddles may exceed their travel; long-period waves near the low modes of the main span can produce girder displacements far larger than an acceleration-spectrum estimate. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":20}],"order":4},{"id":"b003-v13-s2","title":"材料、構件與接合細部","titleEn":"Materials, members and connection details","description":"本階段聚焦「高強度鋼絲與單纜斷面」與「設置沉箱與抗水洗混凝土」：先建立傳力機制與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"High-strength wire and the single-cable section\" and \"Laying-down caisson and antiwashout concrete\": build the load path and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b003-v13-09","title":"高強度鋼絲與單纜斷面：機制與傳力路徑","titleEn":"High-strength wire and the single-cable section: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-08"],"objective":"說明「1,760 N/mm² 鍍鋅鋼絲」如何影響明石海峽大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “1,760 N/mm² galvanised wire” governs force, deformation or durability in “Akashi Kaikyo Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"主纜是懸索橋最難更換的構件，其強度決定跨度上限。本州四國連絡橋公團公開說明：若沿用 160 kgf/mm²（約 1,570 N/mm²）鋼絲，明石海峽大橋每側需要兩條約 1,000 mm 的主纜；開發 180 kgf/mm²（約 1,760 N/mm²，製造商資料稱 1,770 MPa 級）鋼絲後，每側只需一條約 1,100 mm 主纜。每條主纜由 290 股、每股 127 根 5.23 mm 鍍鋅鋼絲組成。鋼絲強度提高也提高了工作應力，因此鍍鋅層、乾燥空氣與疲勞細部變得更關鍵。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「1,760 N/mm² 鍍鋅鋼絲」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"The main cable is the hardest member of a suspension bridge to replace, and its strength sets the span limit. The Honshu-Shikoku authority states that with 160 kgf/mm² wire (about 1,570 N/mm²) Akashi Kaikyo would have needed two cables of about 1,000 mm on each side; with newly developed 180 kgf/mm² wire (about 1,760 N/mm², quoted by the steelmaker as the 1,770 MPa class) one cable of about 1,100 mm per side sufficed. Each cable has 290 strands of 127 galvanised wires of 5.23 mm. Higher wire strength also raises working stress, so the zinc coating, dry air and fatigue details become more critical. Mentor task: draw a free-body or load-path diagram showing how loads pass through “1,760 N/mm² galvanised wire” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：單絲面積 a = π/4×5.23² = 21.48 mm²，每纜 290×127 = 36,830 根，A = 36,830×21.48 ≈ 791,200 mm²；破斷力 = 791,200×1,760 ≈ 1,393 MN。","observationEn":"Order-of-magnitude cue: Wire area a = π/4×5.23² = 21.48 mm², with 290×127 = 36,830 wires per cable, A = 36,830×21.48 ≈ 791,200 mm²; breaking force = 791,200×1,760 ≈ 1,393 MN.","failure":"常見誤解：「鋼絲強度越高，主纜就越不需要防蝕。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The stronger the wire, the less corrosion protection the cable needs.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「1,760 N/mm² 鍍鋅鋼絲」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “1,760 N/mm² galvanised wire”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b003-v13-09-k1","title":"高強度鋼絲與單纜斷面","titleEn":"High-strength wire and the single-cable section","text":"主纜是懸索橋最難更換的構件，其強度決定跨度上限。本州四國連絡橋公團公開說明：若沿用 160 kgf/mm²（約 1,570 N/mm²）鋼絲，明石海峽大橋每側需要兩條約 1,000 mm 的主纜；開發 180 kgf/mm²（約 1,760 N/mm²，製造商資料稱 1,770 MPa 級）鋼絲後，每側只需一條約 1,100 mm 主纜。","textEn":"The main cable is the hardest member of a suspension bridge to replace, and its strength sets the span limit. The Honshu-Shikoku authority states that with 160 kgf/mm² wire (about 1,570 N/mm²) Akashi Kaikyo would have needed two cables of about 1,000 mm on each side; with newly developed 180 kgf/mm² wire (about 1,760 N/mm², quoted by the steelmaker as the 1,770 MPa class) one cable of about 1,100 mm per side sufficed.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：鋼絲強度越高，主纜就越不需要防蝕。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The stronger the wire, the less corrosion protection the cable needs. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"關於「高強度鋼絲與單纜斷面」，下列哪一項敘述正確？","questionEn":"Which statement about \"High-strength wire and the single-cable section\" is correct?","options":["主纜是懸索橋最難更換的構件，其強度決定跨度上限。","鋼絲強度越高，主纜就越不需要防蝕。","水中混凝土只要配比強度夠高，澆置方式不影響品質。"],"optionsEn":["The main cable is the hardest member of a suspension bridge to replace, and its strength sets the span limit.","The stronger the wire, the less corrosion protection the cable needs.","If the underwater mix is strong enough, the placing method does not affect quality."],"answer":0,"explanation":"主纜是懸索橋最難更換的構件，其強度決定跨度上限。 其餘選項是常見誤解。","explanationEn":"The main cable is the hardest member of a suspension bridge to replace, and its strength sets the span limit. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":21},{"id":"b003-v13-10","title":"高強度鋼絲與單纜斷面：定量估算","titleEn":"High-strength wire and the single-cable section: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-09"],"objective":"以數值模型估算「1,760 N/mm² 鍍鋅鋼絲」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “1,760 N/mm² galvanised wire” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：單絲面積 a = π/4×5.23² = 21.48 mm²，每纜 290×127 = 36,830 根，A = 36,830×21.48 ≈ 791,200 mm²；破斷力 = 791,200×1,760 ≈ 1,393 MN。若用 1,570 N/mm² 鋼絲提供相同破斷力需 886,900 mm²，多約 12%。主纜外徑約 1.122 m，毛面積 0.989 m²，空隙率 = 1 − 0.791/0.989 ≈ 20%。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Wire area a = π/4×5.23² = 21.48 mm², with 290×127 = 36,830 wires per cable, A = 36,830×21.48 ≈ 791,200 mm²; breaking force = 791,200×1,760 ≈ 1,393 MN. Supplying the same force with 1,570 N/mm² wire needs 886,900 mm², about 12% more. With an outer diameter of about 1.122 m the gross area is 0.989 m² and the void ratio = 1 − 0.791/0.989 ≈ 20%. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：鋼絲出廠要逐捲抽驗抗拉強度、伸長率、扭轉與捲繞試驗及鍍鋅附著量（製造商資料指出長大橋鋼絲鍍鋅量常在 300 g/m² 以上），索股完成後量測長度標記與直徑；架設後以纜徑量測與空隙率計算確認擠壓品質。","observationEn":"How to cross-check: Sample every coil for tensile strength, elongation, torsion and wrapping tests and zinc coating mass (the steelmaker notes that long-span bridge wire is usually coated with 300 g/m² or more), check length marks and diameter on each finished strand, and after erection confirm squeezing quality by measured cable diameter and computed void ratio.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b003-v13-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"單絲面積 a = π/4×5.23² = 21.48 mm²，每纜 290×127 = 36,830 根，A = 36,830×21.48 ≈ 791,200 mm²；破斷力 = 791,200×1,760 ≈ 1,393 MN。若用 1,570 N/mm² 鋼絲提供相同破斷力需 886,900 mm²，多約 12%。主纜外徑約 1.122 m，毛面積 0.989 m²，空隙率 = 1 − 0.791/0.989 ≈ 20%。","textEn":"Wire area a = π/4×5.23² = 21.48 mm², with 290×127 = 36,830 wires per cable, A = 36,830×21.48 ≈ 791,200 mm²; breaking force = 791,200×1,760 ≈ 1,393 MN. Supplying the same force with 1,570 N/mm² wire needs 886,900 mm², about 12% more. With an outer diameter of about 1.122 m the gross area is 0.989 m² and the void ratio = 1 − 0.791/0.989 ≈ 20%.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"依「高強度鋼絲與單纜斷面」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"High-strength wire and the single-cable section\", which statement holds?","options":["地震後只要把橋塔推回原位，就能維持原設計線形。","單絲面積 a = π/4×5.23² = 21.48 mm²，每纜 290×127 = 36,830 根，A = 36,830×21.48 ≈ 791,200 mm²。","只要吊索間距大於 5 倍直徑，就不會有尾流振動。"],"optionsEn":["After an earthquake you simply push the towers back to restore the design profile.","Wire area a = π/4×5.23² = 21.48 mm², with 290×127 = 36,830 wires per cable, A = 36,830×21.48 ≈ 791,200 mm²; breaking force = 791,200×1,760 ≈ 1,393 MN.","Hangers spaced more than five diameters apart can never suffer wake vibration."],"answer":1,"explanation":"單絲面積 a = π/4×5.23² = 21.48 mm²，每纜 290×127 = 36,830 根，A = 36,830×21.48 ≈ 791,200 mm²；破斷力 = 791,200×1,760 ≈ 1,393 MN。 重算時請保留單位。","explanationEn":"Wire area a = π/4×5.23² = 21.48 mm², with 290×127 = 36,830 wires per cable, A = 36,830×21.48 ≈ 791,200 mm²; breaking force = 791,200×1,760 ≈ 1,393 MN. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":22},{"id":"b003-v13-11","title":"高強度鋼絲與單纜斷面：試驗與驗證","titleEn":"High-strength wire and the single-cable section: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「1,760 N/mm² 鍍鋅鋼絲」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “1,760 N/mm² galvanised wire” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"鋼絲出廠要逐捲抽驗抗拉強度、伸長率、扭轉與捲繞試驗及鍍鋅附著量（製造商資料指出長大橋鋼絲鍍鋅量常在 300 g/m² 以上），索股完成後量測長度標記與直徑；架設後以纜徑量測與空隙率計算確認擠壓品質。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Sample every coil for tensile strength, elongation, torsion and wrapping tests and zinc coating mass (the steelmaker notes that long-span bridge wire is usually coated with 300 g/m² or more), check length marks and diameter on each finished strand, and after erection confirm squeezing quality by measured cable diameter and computed void ratio. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：鋼絲規格要同時規定強度、韌性指標（扭轉次數）與鍍鋅量，並要求每捲可追溯到爐號；擠壓與纏絲作業須設保護措施避免刮傷鍍鋅層，損傷處的修補方法與允收須事先核准。","observationEn":"Site practice: Wire specifications must set strength, ductility indicators such as torsion turns and zinc mass together, with every coil traceable to its heat; squeezing and wrapping must protect the zinc from scratches, and repair methods and acceptance for damaged spots must be approved in advance.","failure":"注意干擾：高強度鋼絲對氫脆與應力腐蝕更敏感，鍍鋅層若在運輸或擠壓時刮傷，加上潮濕空氣，就可能出現局部腐蝕坑與脆性斷絲；斷絲在纜內不易察覺，累積到一定比例才顯現為安全係數下降。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: High-strength wire is more sensitive to hydrogen embrittlement and stress corrosion; zinc scratched during transport or squeezing, combined with humid air, can start local pits and brittle wire breaks that are hard to see inside the cable and only appear as a loss of safety factor once enough have accumulated. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b003-v13-11-k1","title":"驗證方法","titleEn":"Verification method","text":"鋼絲出廠要逐捲抽驗抗拉強度、伸長率、扭轉與捲繞試驗及鍍鋅附著量（製造商資料指出長大橋鋼絲鍍鋅量常在 300 g/m² 以上），索股完成後量測長度標記與直徑；架設後以纜徑量測與空隙率計算確認擠壓品質。","textEn":"Sample every coil for tensile strength, elongation, torsion and wrapping tests and zinc coating mass (the steelmaker notes that long-span bridge wire is usually coated with 300 g/m² or more), check length marks and diameter on each finished strand, and after erection confirm squeezing quality by measured cable diameter and computed void ratio.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-11-k2","title":"現場實務","titleEn":"Site practice","text":"鋼絲規格要同時規定強度、韌性指標（扭轉次數）與鍍鋅量，並要求每捲可追溯到爐號；擠壓與纏絲作業須設保護措施避免刮傷鍍鋅層，損傷處的修補方法與允收須事先核准。","textEn":"Wire specifications must set strength, ductility indicators such as torsion turns and zinc mass together, with every coil traceable to its heat; squeezing and wrapping must protect the zinc from scratches, and repair methods and acceptance for damaged spots must be approved in advance.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"要驗證「高強度鋼絲與單纜斷面」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"High-strength wire and the single-cable section\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","減振裝置維護得越頻繁，橋梁一定越安全。","鋼絲出廠要逐捲抽驗抗拉強度、伸長率、扭轉與捲繞試驗及鍍鋅附著量（製造商資料指出長大橋鋼絲鍍鋅量常在 300 g/m² 以上），索股完成後量測長度標記與直徑。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","The more often dampers are serviced, the safer the bridge must be.","Sample every coil for tensile strength, elongation, torsion and wrapping tests and zinc coating mass (the steelmaker notes that long-span bridge wire is usually coated with 300 g/m² or more), check length marks and diameter on each finished strand, and after erection confirm squeezing quality by measured cable diameter and computed void ratio."],"answer":2,"explanation":"鋼絲出廠要逐捲抽驗抗拉強度、伸長率、扭轉與捲繞試驗及鍍鋅附著量（製造商資料指出長大橋鋼絲鍍鋅量常在 300 g/m² 以上），索股完成後量測長度標記與直徑；架設後以纜徑量測與空隙率計算確認擠壓品質。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Sample every coil for tensile strength, elongation, torsion and wrapping tests and zinc coating mass (the steelmaker notes that long-span bridge wire is usually coated with 300 g/m² or more), check length marks and diameter on each finished strand, and after erection confirm squeezing quality by measured cable diameter and computed void ratio. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":23},{"id":"b003-v13-12","title":"高強度鋼絲與單纜斷面：失效診斷","titleEn":"High-strength wire and the single-cable section: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-11"],"objective":"從症狀倒推「1,760 N/mm² 鍍鋅鋼絲」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “1,760 N/mm² galvanised wire” and propose discriminating checks, corrective actions and prevention.","instruction":"高強度鋼絲對氫脆與應力腐蝕更敏感，鍍鋅層若在運輸或擠壓時刮傷，加上潮濕空氣，就可能出現局部腐蝕坑與脆性斷絲；斷絲在纜內不易察覺，累積到一定比例才顯現為安全係數下降。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"High-strength wire is more sensitive to hydrogen embrittlement and stress corrosion; zinc scratched during transport or squeezing, combined with humid air, can start local pits and brittle wire breaks that are hard to see inside the cable and only appear as a loss of safety factor once enough have accumulated. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：鋼絲強度提高也提高了工作應力，因此鍍鋅層、乾燥空氣與疲勞細部變得更關鍵。","observationEn":"Link to the mechanism: Higher wire strength also raises working stress, so the zinc coating, dry air and fatigue details become more critical.","failure":"誤判風險：若相信「鋼絲強度越高，主纜就越不需要防蝕。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The stronger the wire, the less corrosion protection the cable needs.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b003-v13-12-k1","title":"失效模式","titleEn":"Failure mode","text":"高強度鋼絲對氫脆與應力腐蝕更敏感，鍍鋅層若在運輸或擠壓時刮傷，加上潮濕空氣，就可能出現局部腐蝕坑與脆性斷絲；斷絲在纜內不易察覺，累積到一定比例才顯現為安全係數下降。","textEn":"High-strength wire is more sensitive to hydrogen embrittlement and stress corrosion; zinc scratched during transport or squeezing, combined with humid air, can start local pits and brittle wire breaks that are hard to see inside the cable and only appear as a loss of safety factor once enough have accumulated.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"在「高強度鋼絲與單纜斷面」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"High-strength wire and the single-cable section\" shows distress, which diagnosis is most reasonable?","options":["高強度鋼絲對氫脆與應力腐蝕更敏感，鍍鋅層若在運輸或擠壓時刮傷，加上潮濕空氣，就可能出現局部腐蝕坑與脆性斷絲。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","水中混凝土只要配比強度夠高，澆置方式不影響品質。"],"optionsEn":["High-strength wire is more sensitive to hydrogen embrittlement and stress corrosion.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","If the underwater mix is strong enough, the placing method does not affect quality."],"answer":0,"explanation":"高強度鋼絲對氫脆與應力腐蝕更敏感，鍍鋅層若在運輸或擠壓時刮傷，加上潮濕空氣，就可能出現局部腐蝕坑與脆性斷絲；斷絲在纜內不易察覺，累積到一定比例才顯現為安全係數下降。 需以量測區分可能原因。","explanationEn":"High-strength wire is more sensitive to hydrogen embrittlement and stress corrosion; zinc scratched during transport or squeezing, combined with humid air, can start local pits and brittle wire breaks that are hard to see inside the cable and only appear as a loss of safety factor once enough have accumulated. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":24},{"id":"b003-v13-13","title":"設置沉箱與抗水洗混凝土：機制與傳力路徑","titleEn":"Laying-down caisson and antiwashout concrete: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-12"],"objective":"說明「2P 鋼沉箱與水中混凝土」如何影響明石海峽大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “2P steel caisson and underwater concrete” governs force, deformation or durability in “Akashi Kaikyo Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"主塔基礎位於水深約 60 m、潮流最大約 8 節的海峽中，無法築圍堰抽乾。做法是先開挖整平海床，再把工廠製造的雙壁圓形鋼沉箱拖航到位、灌水沉放（設置沉箱工法），然後在沉箱內以抗水洗水中混凝土分層澆置，讓鋼殼成為永久模板。2P 沉箱外徑 80 m、內徑 56 m、高約 65 m，內核混凝土約 270,000 m³；基礎周邊再鋪濾層與拋石防止強潮流沖刷。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「2P 鋼沉箱與水中混凝土」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"The tower foundations sit in about 60 m of water with tidal currents up to about 8 knots, where no cofferdam can be pumped dry. The seabed is excavated and levelled, a factory-built double-walled circular steel caisson is towed into place and ballasted down (the laying-down caisson method), and antiwashout underwater concrete is then placed in layers inside it, the steel shell acting as permanent formwork. The 2P caisson is 80 m in outer diameter, 56 m inner, about 65 m high, with about 270,000 m³ of core concrete; filter layers and rock armour around it resist scour by the strong currents. Mentor task: draw a free-body or load-path diagram showing how loads pass through “2P steel caisson and underwater concrete” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：內核面積 = π/4×56² ≈ 2,463 m²，每層 4 m，單次澆置約 2,463×4 ≈ 9,850 m³，連續約 72 h，平均 9,850/72 ≈ 137 m³/h；六台泵各 110 m³/h，總能力 660 m³/h，平均利用率約 21%。","observationEn":"Order-of-magnitude cue: Core area = π/4×56² ≈ 2,463 m²; with 4 m layers each pour is about 2,463×4 ≈ 9,850 m³, placed continuously over about 72 h, an average of 9,850/72 ≈ 137 m³/h; six pumps of 110 m³/h give 660 m³/h of capacity, about 21% average utilisation.","failure":"常見誤解：「水中混凝土只要配比強度夠高，澆置方式不影響品質。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"If the underwater mix is strong enough, the placing method does not affect quality.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「2P 鋼沉箱與水中混凝土」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “2P steel caisson and underwater concrete”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b003-v13-13-k1","title":"設置沉箱與抗水洗混凝土","titleEn":"Laying-down caisson and antiwashout concrete","text":"主塔基礎位於水深約 60 m、潮流最大約 8 節的海峽中，無法築圍堰抽乾。做法是先開挖整平海床，再把工廠製造的雙壁圓形鋼沉箱拖航到位、灌水沉放（設置沉箱工法），然後在沉箱內以抗水洗水中混凝土分層澆置，讓鋼殼成為永久模板。","textEn":"The tower foundations sit in about 60 m of water with tidal currents up to about 8 knots, where no cofferdam can be pumped dry. The seabed is excavated and levelled, a factory-built double-walled circular steel caisson is towed into place and ballasted down (the laying-down caisson method), and antiwashout underwater concrete is then placed in layers inside it, the steel shell acting as permanent formwork.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：水中混凝土只要配比強度夠高，澆置方式不影響品質。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: If the underwater mix is strong enough, the placing method does not affect quality. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"關於「設置沉箱與抗水洗混凝土」，下列哪一項敘述正確？","questionEn":"Which statement about \"Laying-down caisson and antiwashout concrete\" is correct?","options":["水中混凝土只要配比強度夠高，澆置方式不影響品質。","主塔基礎位於水深約 60 m、潮流最大約 8 節的海峽中，無法築圍堰抽乾。","索股垂度只要白天量一次，誤差幾公分不影響主纜受力。"],"optionsEn":["If the underwater mix is strong enough, the placing method does not affect quality.","The tower foundations sit in about 60 m of water with tidal currents up to about 8 knots, where no cofferdam can be pumped dry.","Measuring strand sag once in daytime is fine; a few centimetres of error do not affect cable forces."],"answer":1,"explanation":"主塔基礎位於水深約 60 m、潮流最大約 8 節的海峽中，無法築圍堰抽乾。 其餘選項是常見誤解。","explanationEn":"The tower foundations sit in about 60 m of water with tidal currents up to about 8 knots, where no cofferdam can be pumped dry. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":25},{"id":"b003-v13-14","title":"設置沉箱與抗水洗混凝土：定量估算","titleEn":"Laying-down caisson and antiwashout concrete: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-13"],"objective":"以數值模型估算「2P 鋼沉箱與水中混凝土」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “2P steel caisson and underwater concrete” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：內核面積 = π/4×56² ≈ 2,463 m²，每層 4 m，單次澆置約 2,463×4 ≈ 9,850 m³，連續約 72 h，平均 9,850/72 ≈ 137 m³/h；六台泵各 110 m³/h，總能力 660 m³/h，平均利用率約 21%。24 支澆置管平均各負責 2,463/24 ≈ 103 m²，等效半徑 √(103/π) ≈ 5.7 m，小於 8 m 流動距離上限。面積與層厚引自公開論文，其餘為推算。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Core area = π/4×56² ≈ 2,463 m²; with 4 m layers each pour is about 2,463×4 ≈ 9,850 m³, placed continuously over about 72 h, an average of 9,850/72 ≈ 137 m³/h; six pumps of 110 m³/h give 660 m³/h of capacity, about 21% average utilisation. Each of 24 tremie pipes serves about 2,463/24 ≈ 103 m², an equivalent radius of √(103/π) ≈ 5.7 m, within the 8 m flow-distance limit. Area and layer thickness come from a published paper; the rest is derived. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：澆置中以測深錘或感測器追蹤各管周邊混凝土面高程，確保管口埋入深度與層面平整；試體量測水中與氣中強度比、坍流度與凝結時間；完成後鑽心取樣檢查層間結合與空洞，並以海床測深監測沉箱周邊沖刷。","observationEn":"How to cross-check: During placement track the concrete surface around each pipe with sounding weights or sensors to keep pipe embedment and a level surface; test specimens for the underwater-to-air strength ratio, slump flow and setting time; afterwards core through layers to check bond and voids, and monitor scour around the caisson by seabed soundings.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b003-v13-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"內核面積 = π/4×56² ≈ 2,463 m²，每層 4 m，單次澆置約 2,463×4 ≈ 9,850 m³，連續約 72 h，平均 9,850/72 ≈ 137 m³/h；六台泵各 110 m³/h，總能力 660 m³/h，平均利用率約 21%。24 支澆置管平均各負責 2,463/24 ≈ 103 m²，等效半徑 √(103/π) ≈ 5.7 m，小於 8 m 流動距離上限。面積與層厚引自公開論文，其餘為推算。","textEn":"Core area = π/4×56² ≈ 2,463 m²; with 4 m layers each pour is about 2,463×4 ≈ 9,850 m³, placed continuously over about 72 h, an average of 9,850/72 ≈ 137 m³/h; six pumps of 110 m³/h give 660 m³/h of capacity, about 21% average utilisation. Each of 24 tremie pipes serves about 2,463/24 ≈ 103 m², an equivalent radius of √(103/π) ≈ 5.7 m, within the 8 m flow-distance limit. Area and layer thickness come from a published paper; the rest is derived.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"依「設置沉箱與抗水洗混凝土」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Laying-down caisson and antiwashout concrete\", which statement holds?","options":["全橋模型的風速必須和實橋一樣，試驗才有意義。","主纜外面有鍍鋅纏絲與塗裝，內部就不會潮濕。","內核面積 = π/4×56² ≈ 2,463 m²，每層 4 m，單次澆置約 2,463×4 ≈ 9,850 m³，連續約 72 h，平均 9,850/72 ≈ 137 m³/h。"],"optionsEn":["A full-bridge model is only meaningful if tested at the same wind speed as the real bridge.","With galvanised wrapping and paint outside, the cable interior cannot get wet.","Core area = π/4×56² ≈ 2,463 m²."],"answer":2,"explanation":"內核面積 = π/4×56² ≈ 2,463 m²，每層 4 m，單次澆置約 2,463×4 ≈ 9,850 m³，連續約 72 h，平均 9,850/72 ≈ 137 m³/h；六台泵各 110 m³/h，總能力 660 m³/h，平均利用率約 21%。 重算時請保留單位。","explanationEn":"Core area = π/4×56² ≈ 2,463 m²; with 4 m layers each pour is about 2,463×4 ≈ 9,850 m³, placed continuously over about 72 h, an average of 9,850/72 ≈ 137 m³/h; six pumps of 110 m³/h give 660 m³/h of capacity, about 21% average utilisation. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":26},{"id":"b003-v13-15","title":"設置沉箱與抗水洗混凝土：試驗與驗證","titleEn":"Laying-down caisson and antiwashout concrete: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「2P 鋼沉箱與水中混凝土」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “2P steel caisson and underwater concrete” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"澆置中以測深錘或感測器追蹤各管周邊混凝土面高程，確保管口埋入深度與層面平整；試體量測水中與氣中強度比、坍流度與凝結時間；完成後鑽心取樣檢查層間結合與空洞，並以海床測深監測沉箱周邊沖刷。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"During placement track the concrete surface around each pipe with sounding weights or sensors to keep pipe embedment and a level surface; test specimens for the underwater-to-air strength ratio, slump flow and setting time; afterwards core through layers to check bond and voids, and monitor scour around the caisson by seabed soundings. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：水中混凝土計畫應規定管口最小埋深、最大流動距離、層間間隔時間與停止條件，並在試驗槽先做足尺試澆；沉箱就位精度與海床整平度列為進入澆置前的停留點，由監造簽認。","observationEn":"Site practice: The underwater concreting plan must fix minimum pipe embedment, maximum flow distance, layer interval and stop conditions, with a full-scale trial pour in a test tank; caisson positioning accuracy and seabed levelness are hold points signed by the supervising engineer before placement begins.","failure":"注意干擾：水中混凝土若抗水洗性不足或管口拔出，水泥漿被潮流帶走，形成骨材鬆散層與層間弱面；某一區流動距離過長則產生材料分離。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Concrete with poor washout resistance, or a pipe lifted out of the mass, lets the current strip the paste and leaves loose aggregate and weak layer joints; excessive flow distance in one zone causes segregation. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b003-v13-15-k1","title":"驗證方法","titleEn":"Verification method","text":"澆置中以測深錘或感測器追蹤各管周邊混凝土面高程，確保管口埋入深度與層面平整；試體量測水中與氣中強度比、坍流度與凝結時間；完成後鑽心取樣檢查層間結合與空洞，並以海床測深監測沉箱周邊沖刷。","textEn":"During placement track the concrete surface around each pipe with sounding weights or sensors to keep pipe embedment and a level surface; test specimens for the underwater-to-air strength ratio, slump flow and setting time; afterwards core through layers to check bond and voids, and monitor scour around the caisson by seabed soundings.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-15-k2","title":"現場實務","titleEn":"Site practice","text":"水中混凝土計畫應規定管口最小埋深、最大流動距離、層間間隔時間與停止條件，並在試驗槽先做足尺試澆；沉箱就位精度與海床整平度列為進入澆置前的停留點，由監造簽認。","textEn":"The underwater concreting plan must fix minimum pipe embedment, maximum flow distance, layer interval and stop conditions, with a full-scale trial pour in a test tank; caisson positioning accuracy and seabed levelness are hold points signed by the supervising engineer before placement begins.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"要驗證「設置沉箱與抗水洗混凝土」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Laying-down caisson and antiwashout concrete\"?","options":["澆置中以測深錘或感測器追蹤各管周邊混凝土面高程，確保管口埋入深度與層面平整。","不確定度太難估計，報告中只寫最佳值即可。","桁架加勁梁很深很重，所以不會發生顫振。"],"optionsEn":["During placement track the concrete surface around each pipe with sounding weights or sensors to keep pipe embedment and a level surface.","Uncertainty is too hard to estimate, so the report may state only the best value.","A truss stiffening girder is deep and heavy, so it cannot flutter."],"answer":0,"explanation":"澆置中以測深錘或感測器追蹤各管周邊混凝土面高程，確保管口埋入深度與層面平整；試體量測水中與氣中強度比、坍流度與凝結時間；完成後鑽心取樣檢查層間結合與空洞，並以海床測深監測沉箱周邊沖刷。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"During placement track the concrete surface around each pipe with sounding weights or sensors to keep pipe embedment and a level surface; test specimens for the underwater-to-air strength ratio, slump flow and setting time; afterwards core through layers to check bond and voids, and monitor scour around the caisson by seabed soundings. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":27},{"id":"b003-v13-16","title":"設置沉箱與抗水洗混凝土：失效診斷","titleEn":"Laying-down caisson and antiwashout concrete: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-15"],"objective":"從症狀倒推「2P 鋼沉箱與水中混凝土」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “2P steel caisson and underwater concrete” and propose discriminating checks, corrective actions and prevention.","instruction":"水中混凝土若抗水洗性不足或管口拔出，水泥漿被潮流帶走，形成骨材鬆散層與層間弱面；某一區流動距離過長則產生材料分離。基礎周邊沖刷若未及時防護，可能淘空沉箱邊緣、降低承載與抗傾覆能力。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Concrete with poor washout resistance, or a pipe lifted out of the mass, lets the current strip the paste and leaves loose aggregate and weak layer joints; excessive flow distance in one zone causes segregation. Unchecked scour around the foundation can undermine the caisson edge and reduce bearing and overturning capacity. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：2P 沉箱外徑 80 m、內徑 56 m、高約 65 m，內核混凝土約 270,000 m³；基礎周邊再鋪濾層與拋石防止強潮流沖刷。","observationEn":"Link to the mechanism: The 2P caisson is 80 m in outer diameter, 56 m inner, about 65 m high, with about 270,000 m³ of core concrete; filter layers and rock armour around it resist scour by the strong currents.","failure":"誤判風險：若相信「水中混凝土只要配比強度夠高，澆置方式不影響品質。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"If the underwater mix is strong enough, the placing method does not affect quality.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b003-v13-16-k1","title":"失效模式","titleEn":"Failure mode","text":"水中混凝土若抗水洗性不足或管口拔出，水泥漿被潮流帶走，形成骨材鬆散層與層間弱面；某一區流動距離過長則產生材料分離。基礎周邊沖刷若未及時防護，可能淘空沉箱邊緣、降低承載與抗傾覆能力。","textEn":"Concrete with poor washout resistance, or a pipe lifted out of the mass, lets the current strip the paste and leaves loose aggregate and weak layer joints; excessive flow distance in one zone causes segregation. Unchecked scour around the foundation can undermine the caisson edge and reduce bearing and overturning capacity.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"在「設置沉箱與抗水洗混凝土」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Laying-down caisson and antiwashout concrete\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","水中混凝土若抗水洗性不足或管口拔出，水泥漿被潮流帶走，形成骨材鬆散層與層間弱面；某一區流動距離過長則產生材料分離。","索股垂度只要白天量一次，誤差幾公分不影響主纜受力。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Concrete with poor washout resistance, or a pipe lifted out of the mass, lets the current strip the paste and leaves loose aggregate and weak layer joints.","Measuring strand sag once in daytime is fine; a few centimetres of error do not affect cable forces."],"answer":1,"explanation":"水中混凝土若抗水洗性不足或管口拔出，水泥漿被潮流帶走，形成骨材鬆散層與層間弱面；某一區流動距離過長則產生材料分離。 需以量測區分可能原因。","explanationEn":"Concrete with poor washout resistance, or a pipe lifted out of the mass, lets the current strip the paste and leaves loose aggregate and weak layer joints; excessive flow distance in one zone causes segregation. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":28}],"order":5},{"id":"b003-v13-s3","title":"施工方法與施工階段控制","titleEn":"Construction methods and stage control","description":"本階段聚焦「索股垂度的溫度敏感度」與「跨徑變化後的垂度與桁段修正」：先建立傳力機制與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Temperature sensitivity of strand sag\" and \"Sag change and truss correction after the span grew\": build the load path and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b003-v13-17","title":"索股垂度的溫度敏感度：機制與傳力路徑","titleEn":"Temperature sensitivity of strand sag: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-16"],"objective":"說明「預製平行鋼絲索股垂度」如何影響明石海峽大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “PWS strand sag” governs force, deformation or durability in “Akashi Kaikyo Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"明石海峽大橋以預製平行鋼絲索股（PWS）架設主纜：每股 127 根鋼絲在工廠成束、端部預裝錨頭，再沿導索與貓道牽引過海峽，290 股依序放入索鞍。每一股都必須調整到與基準索股相同的垂度，否則擠壓成纜後各股受力不均。由於主纜長度隨溫度伸縮，而垂度對長度變化極為敏感，調整通常安排在夜間溫度穩定、索股內外溫差小的時段，並以溫度修正量測值。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「預製平行鋼絲索股垂度」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Akashi Kaikyo's main cables were erected with prefabricated parallel-wire strands (PWS): each bundle of 127 wires is made in the factory with sockets fitted at the ends, hauled across the strait along guide ropes and catwalks, and the 290 strands are placed in the saddles in sequence. Every strand must be adjusted to the same sag as the reference strand, otherwise the wires share load unequally after squeezing. Because cable length changes with temperature and sag is very sensitive to length, adjustment is usually done at night when temperatures are stable and the difference between strand surface and core is small, with temperature-corrected readings. Mentor task: draw a free-body or load-path diagram showing how loads pass through “PWS strand sag” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：拋物線纜長 S ≈ l + 8f²/(3l)。","observationEn":"Order-of-magnitude cue: Parabolic cable length S ≈ l + 8f²/(3l).","failure":"常見誤解：「索股垂度只要白天量一次，誤差幾公分不影響主纜受力。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Measuring strand sag once in daytime is fine; a few centimetres of error do not affect cable forces.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「預製平行鋼絲索股垂度」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “PWS strand sag”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b003-v13-17-k1","title":"索股垂度的溫度敏感度","titleEn":"Temperature sensitivity of strand sag","text":"明石海峽大橋以預製平行鋼絲索股（PWS）架設主纜：每股 127 根鋼絲在工廠成束、端部預裝錨頭，再沿導索與貓道牽引過海峽，290 股依序放入索鞍。每一股都必須調整到與基準索股相同的垂度，否則擠壓成纜後各股受力不均。","textEn":"Akashi Kaikyo's main cables were erected with prefabricated parallel-wire strands (PWS): each bundle of 127 wires is made in the factory with sockets fitted at the ends, hauled across the strait along guide ropes and catwalks, and the 290 strands are placed in the saddles in sequence. Every strand must be adjusted to the same sag as the reference strand, otherwise the wires share load unequally after squeezing.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：索股垂度只要白天量一次，誤差幾公分不影響主纜受力。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Measuring strand sag once in daytime is fine; a few centimetres of error do not affect cable forces. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"關於「索股垂度的溫度敏感度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Temperature sensitivity of strand sag\" is correct?","options":["索股垂度只要白天量一次，誤差幾公分不影響主纜受力。","地震後只要把橋塔推回原位，就能維持原設計線形。","明石海峽大橋以預製平行鋼絲索股（PWS）架設主纜：每股 127 根鋼絲在工廠成束、端部預裝錨頭，再沿導索與貓道牽引過海峽，290 股依序放入索鞍。"],"optionsEn":["Measuring strand sag once in daytime is fine; a few centimetres of error do not affect cable forces.","After an earthquake you simply push the towers back to restore the design profile.","Akashi Kaikyo's main cables were erected with prefabricated parallel-wire strands (PWS): each bundle of 127 wires is made in the factory with sockets fitted at the ends, hauled across the strait along guide ropes and catwalks, and the 290 strands are placed in the saddles in sequence."],"answer":2,"explanation":"明石海峽大橋以預製平行鋼絲索股（PWS）架設主纜：每股 127 根鋼絲在工廠成束、端部預裝錨頭，再沿導索與貓道牽引過海峽，290 股依序放入索鞍。 其餘選項是常見誤解。","explanationEn":"Akashi Kaikyo's main cables were erected with prefabricated parallel-wire strands (PWS): each bundle of 127 wires is made in the factory with sockets fitted at the ends, hauled across the strait along guide ropes and catwalks, and the 290 strands are placed in the saddles in sequence. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":29},{"id":"b003-v13-18","title":"索股垂度的溫度敏感度：定量估算","titleEn":"Temperature sensitivity of strand sag: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-17"],"objective":"以數值模型估算「預製平行鋼絲索股垂度」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “PWS strand sag” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：拋物線纜長 S ≈ l + 8f²/(3l)。取 l = 1,991 m、f = 199.1 m（垂跨比 1/10）：S ≈ 1,991 + 53.1 = 2,044.1 m。溫度上升 1 °C，ΔS = 1.2×10⁻⁵×2,044.1 ≈ 0.0245 m，Δf = (3l/(16f))·ΔS = 1.875×0.0245 ≈ 0.046 m。也就是每 1 °C 垂度約改變 46 mm，5 °C 溫差即約 230 mm。數值為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Parabolic cable length S ≈ l + 8f²/(3l). With l = 1,991 m and f = 199.1 m (sag ratio 1/10): S ≈ 1,991 + 53.1 = 2,044.1 m. A 1 °C rise gives ΔS = 1.2×10⁻⁵×2,044.1 ≈ 0.0245 m and Δf = (3l/(16f))·ΔS = 1.875×0.0245 ≈ 0.046 m, so sag changes by about 46 mm per °C and a 5 °C error means about 230 mm. Values are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：基準索股以全站儀或水準量測跨中與邊跨垂度，配合多點索股溫度計取平均溫度修正；其他索股以相對於基準股的高差量測調整，允收以修正後高差在數毫米至十餘毫米內為準。","observationEn":"How to cross-check: Measure mid-span and side-span sag of the reference strand by total station or levelling with multi-point strand thermometers for temperature correction; adjust other strands by their height difference relative to the reference, accepting corrected differences within a few to about a dozen millimetres.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b003-v13-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"拋物線纜長 S ≈ l + 8f²/(3l)。取 l = 1,991 m、f = 199.1 m（垂跨比 1/10）：S ≈ 1,991 + 53.1 = 2,044.1 m。溫度上升 1 °C，ΔS = 1.2×10⁻⁵×2,044.1 ≈ 0.0245 m，Δf = (3l/(16f))·ΔS = 1.875×0.0245 ≈ 0.046 m。也就是每 1 °C 垂度約改變 46 mm，5 °C 溫差即約 230 mm。數值為教學假設。","textEn":"Parabolic cable length S ≈ l + 8f²/(3l). With l = 1,991 m and f = 199.1 m (sag ratio 1/10): S ≈ 1,991 + 53.1 = 2,044.1 m. A 1 °C rise gives ΔS = 1.2×10⁻⁵×2,044.1 ≈ 0.0245 m and Δf = (3l/(16f))·ΔS = 1.875×0.0245 ≈ 0.046 m, so sag changes by about 46 mm per °C and a 5 °C error means about 230 mm. Values are teaching assumptions.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"依「索股垂度的溫度敏感度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Temperature sensitivity of strand sag\", which statement holds?","options":["拋物線纜長 S ≈ l + 8f²/(3l)。","只要吊索間距大於 5 倍直徑，就不會有尾流振動。","減振裝置維護得越頻繁，橋梁一定越安全。"],"optionsEn":["Parabolic cable length S ≈ l + 8f²/(3l).","Hangers spaced more than five diameters apart can never suffer wake vibration.","The more often dampers are serviced, the safer the bridge must be."],"answer":0,"explanation":"拋物線纜長 S ≈ l + 8f²/(3l)。 重算時請保留單位。","explanationEn":"Parabolic cable length S ≈ l + 8f²/(3l). Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":30},{"id":"b003-v13-19","title":"索股垂度的溫度敏感度：試驗與驗證","titleEn":"Temperature sensitivity of strand sag: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「預製平行鋼絲索股垂度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “PWS strand sag” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"基準索股以全站儀或水準量測跨中與邊跨垂度，配合多點索股溫度計取平均溫度修正；其他索股以相對於基準股的高差量測調整，允收以修正後高差在數毫米至十餘毫米內為準。每日記錄氣溫、風速與量測時間，作為異常時的回溯依據。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure mid-span and side-span sag of the reference strand by total station or levelling with multi-point strand thermometers for temperature correction; adjust other strands by their height difference relative to the reference, accepting corrected differences within a few to about a dozen millimetres. Log air temperature, wind speed and time daily as a trace for anomalies. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：索股調整的量測時段、溫度計位置與修正公式應寫入施工規範；基準索股須定期複測，若連續數股偏差同向，先停工檢查基準點與溫度修正，再繼續牽引。","observationEn":"Site practice: The specification should fix the measuring window, thermometer positions and correction formula for strand adjustment; the reference strand must be re-surveyed periodically, and if several strands deviate in the same direction, stop to check the benchmarks and temperature correction before hauling more.","failure":"注意干擾：日間陽光照射使上層索股比下層熱數度，若此時調整，夜間冷卻後各股垂度不一，擠壓成纜後部分鋼絲長期過載、部分鬆弛；鬆弛鋼絲在纜內會形成鼓起，影響索夾夾緊與防護包覆。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Adjusting in daytime sun, when top strands run several degrees warmer than lower ones, leaves unequal sags after night cooling; once squeezed, some wires are permanently overloaded and others slack, and slack wires bulge inside the cable, spoiling cable-band clamping and wrapping. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b003-v13-19-k1","title":"驗證方法","titleEn":"Verification method","text":"基準索股以全站儀或水準量測跨中與邊跨垂度，配合多點索股溫度計取平均溫度修正；其他索股以相對於基準股的高差量測調整，允收以修正後高差在數毫米至十餘毫米內為準。每日記錄氣溫、風速與量測時間，作為異常時的回溯依據。","textEn":"Measure mid-span and side-span sag of the reference strand by total station or levelling with multi-point strand thermometers for temperature correction; adjust other strands by their height difference relative to the reference, accepting corrected differences within a few to about a dozen millimetres. Log air temperature, wind speed and time daily as a trace for anomalies.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-19-k2","title":"現場實務","titleEn":"Site practice","text":"索股調整的量測時段、溫度計位置與修正公式應寫入施工規範；基準索股須定期複測，若連續數股偏差同向，先停工檢查基準點與溫度修正，再繼續牽引。","textEn":"The specification should fix the measuring window, thermometer positions and correction formula for strand adjustment; the reference strand must be re-surveyed periodically, and if several strands deviate in the same direction, stop to check the benchmarks and temperature correction before hauling more.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"要驗證「索股垂度的溫度敏感度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Temperature sensitivity of strand sag\"?","options":["允收準則可以等看到量測數據後再決定。","基準索股以全站儀或水準量測跨中與邊跨垂度，配合多點索股溫度計取平均溫度修正；其他索股以相對於基準股的高差量測調整，允收以修正後高差在數毫米至十餘毫米內為準。","懸索橋很柔，所以地震對它幾乎沒有影響。"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Measure mid-span and side-span sag of the reference strand by total station or levelling with multi-point strand thermometers for temperature correction.","A suspension bridge is so flexible that earthquakes hardly affect it."],"answer":1,"explanation":"基準索股以全站儀或水準量測跨中與邊跨垂度，配合多點索股溫度計取平均溫度修正；其他索股以相對於基準股的高差量測調整，允收以修正後高差在數毫米至十餘毫米內為準。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure mid-span and side-span sag of the reference strand by total station or levelling with multi-point strand thermometers for temperature correction; adjust other strands by their height difference relative to the reference, accepting corrected differences within a few to about a dozen millimetres. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":31},{"id":"b003-v13-20","title":"索股垂度的溫度敏感度：失效診斷","titleEn":"Temperature sensitivity of strand sag: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-19"],"objective":"從症狀倒推「預製平行鋼絲索股垂度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “PWS strand sag” and propose discriminating checks, corrective actions and prevention.","instruction":"日間陽光照射使上層索股比下層熱數度，若此時調整，夜間冷卻後各股垂度不一，擠壓成纜後部分鋼絲長期過載、部分鬆弛；鬆弛鋼絲在纜內會形成鼓起，影響索夾夾緊與防護包覆。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Adjusting in daytime sun, when top strands run several degrees warmer than lower ones, leaves unequal sags after night cooling; once squeezed, some wires are permanently overloaded and others slack, and slack wires bulge inside the cable, spoiling cable-band clamping and wrapping. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：由於主纜長度隨溫度伸縮，而垂度對長度變化極為敏感，調整通常安排在夜間溫度穩定、索股內外溫差小的時段，並以溫度修正量測值。","observationEn":"Link to the mechanism: Because cable length changes with temperature and sag is very sensitive to length, adjustment is usually done at night when temperatures are stable and the difference between strand surface and core is small, with temperature-corrected readings.","failure":"誤判風險：若相信「索股垂度只要白天量一次，誤差幾公分不影響主纜受力。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Measuring strand sag once in daytime is fine; a few centimetres of error do not affect cable forces.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b003-v13-20-k1","title":"失效模式","titleEn":"Failure mode","text":"日間陽光照射使上層索股比下層熱數度，若此時調整，夜間冷卻後各股垂度不一，擠壓成纜後部分鋼絲長期過載、部分鬆弛；鬆弛鋼絲在纜內會形成鼓起，影響索夾夾緊與防護包覆。","textEn":"Adjusting in daytime sun, when top strands run several degrees warmer than lower ones, leaves unequal sags after night cooling; once squeezed, some wires are permanently overloaded and others slack, and slack wires bulge inside the cable, spoiling cable-band clamping and wrapping.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"在「索股垂度的溫度敏感度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Temperature sensitivity of strand sag\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","地震後只要把橋塔推回原位，就能維持原設計線形。","日間陽光照射使上層索股比下層熱數度，若此時調整，夜間冷卻後各股垂度不一，擠壓成纜後部分鋼絲長期過載、部分鬆弛；鬆弛鋼絲在纜內會形成鼓起，影響索夾夾緊與防護包覆。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","After an earthquake you simply push the towers back to restore the design profile.","Adjusting in daytime sun, when top strands run several degrees warmer than lower ones, leaves unequal sags after night cooling."],"answer":2,"explanation":"日間陽光照射使上層索股比下層熱數度，若此時調整，夜間冷卻後各股垂度不一，擠壓成纜後部分鋼絲長期過載、部分鬆弛；鬆弛鋼絲在纜內會形成鼓起，影響索夾夾緊與防護包覆。 需以量測區分可能原因。","explanationEn":"Adjusting in daytime sun, when top strands run several degrees warmer than lower ones, leaves unequal sags after night cooling; once squeezed, some wires are permanently overloaded and others slack, and slack wires bulge inside the cable, spoiling cable-band clamping and wrapping. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":32},{"id":"b003-v13-21","title":"跨徑變化後的垂度與桁段修正：機制與傳力路徑","titleEn":"Sag change and truss correction after the span grew: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-20"],"objective":"說明「1995 年地震後桁段加長」如何影響明石海峽大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “Post-1995 truss lengthening” governs force, deformation or durability in “Akashi Kaikyo Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"1995 年 1 月 17 日地震發生時，主塔已完成、所有索股已架設，正在進行主纜擠壓，加勁桁尚未架設。斷層錯動使基礎隨地盤移動，中央跨徑約增加 0.8 m。由於主纜長度已固定，跨徑變長意味著垂度變小、張力略增；設計團隊重新計算後，把尚未製造的加勁桁構件在中央跨加長 800 mm、淡路側邊跨加長 340 mm，使完工線形仍與主纜幾何相容。公開論文指出中央跨垂度約減少 1.3 m，主纜張力增加約為原設計最大張力的 0.6%，仍在容許範圍內。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「1995 年地震後桁段加長」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"When the earthquake struck on 17 January 1995 the towers were complete and all strands erected, cable squeezing was in progress and the stiffening truss had not yet been erected. Fault movement carried the foundations with the ground and lengthened the centre span by about 0.8 m. With the cable length already fixed, a longer span means less sag and slightly more tension; after re-analysis the team lengthened truss members not yet fabricated by 800 mm in the centre span and 340 mm in the Awaji side span so that the completed profile stayed compatible with the cable geometry. The published paper reports a centre-span sag reduction of about 1.3 m and an extra cable tension of about 0.6% of the original maximum, within the allowable. Mentor task: draw a free-body or load-path diagram showing how loads pass through “Post-1995 truss lengthening” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：纜長固定時 dS = (1 − 8n²/3)·dl + (16f/(3l))·df = 0，故 df = −dl·(1 − 8n²/3)·3l/(16f)。","observationEn":"Order-of-magnitude cue: With fixed cable length dS = (1 − 8n²/3)·dl + (16f/(3l))·df = 0, so df = −dl·(1 − 8n²/3)·3l/(16f).","failure":"常見誤解：「地震後只要把橋塔推回原位，就能維持原設計線形。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"After an earthquake you simply push the towers back to restore the design profile.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「1995 年地震後桁段加長」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “Post-1995 truss lengthening”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b003-v13-21-k1","title":"跨徑變化後的垂度與桁段修正","titleEn":"Sag change and truss correction after the span grew","text":"1995 年 1 月 17 日地震發生時，主塔已完成、所有索股已架設，正在進行主纜擠壓，加勁桁尚未架設。斷層錯動使基礎隨地盤移動，中央跨徑約增加 0.8 m。","textEn":"When the earthquake struck on 17 January 1995 the towers were complete and all strands erected, cable squeezing was in progress and the stiffening truss had not yet been erected. Fault movement carried the foundations with the ground and lengthened the centre span by about 0.8 m.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：地震後只要把橋塔推回原位，就能維持原設計線形。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: After an earthquake you simply push the towers back to restore the design profile. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"關於「跨徑變化後的垂度與桁段修正」，下列哪一項敘述正確？","questionEn":"Which statement about \"Sag change and truss correction after the span grew\" is correct?","options":["1995 年 1 月 17 日地震發生時，主塔已完成、所有索股已架設，正在進行主纜擠壓，加勁桁尚未架設。","地震後只要把橋塔推回原位，就能維持原設計線形。","全橋模型的風速必須和實橋一樣，試驗才有意義。"],"optionsEn":["When the earthquake struck on 17 January 1995 the towers were complete and all strands erected, cable squeezing was in progress and the stiffening truss had not yet been erected.","After an earthquake you simply push the towers back to restore the design profile.","A full-bridge model is only meaningful if tested at the same wind speed as the real bridge."],"answer":0,"explanation":"1995 年 1 月 17 日地震發生時，主塔已完成、所有索股已架設，正在進行主纜擠壓，加勁桁尚未架設。 其餘選項是常見誤解。","explanationEn":"When the earthquake struck on 17 January 1995 the towers were complete and all strands erected, cable squeezing was in progress and the stiffening truss had not yet been erected. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":33},{"id":"b003-v13-22","title":"跨徑變化後的垂度與桁段修正：定量估算","titleEn":"Sag change and truss correction after the span grew: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-21"],"objective":"以數值模型估算「1995 年地震後桁段加長」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Post-1995 truss lengthening” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：纜長固定時 dS = (1 − 8n²/3)·dl + (16f/(3l))·df = 0，故 df = −dl·(1 − 8n²/3)·3l/(16f)。取 n = 0.1、l = 1,991 m、f = 199.1 m、dl = 0.8 m：df = −0.8×0.973×1.875 ≈ −1.46 m。不可伸長假設高估了垂度變化；實際張力增加使主纜彈性伸長、塔頂也有變位，公開報告值約 1.3 m。n 為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: With fixed cable length dS = (1 − 8n²/3)·dl + (16f/(3l))·df = 0, so df = −dl·(1 − 8n²/3)·3l/(16f). With n = 0.1, l = 1,991 m, f = 199.1 m and dl = 0.8 m: df = −0.8×0.973×1.875 ≈ −1.46 m. The inextensible assumption overestimates the change; the extra tension stretches the cable elastically and the tower tops also move, and the published value is about 1.3 m. n is a teaching assumption. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：事件後以 GPS 與精密測量重新建立各基礎與塔頂座標，量測主纜各跨垂度與索鞍位置，回饋到完工線形分析；加長的桁段在工廠以修正圖說製造，架設中逐段比對節點高程與預測值，最終與設計車道縱斷面比較。","observationEn":"How to cross-check: After the event re-establish coordinates of every foundation and tower top by GPS and precise survey, measure cable sag in each span and saddle positions, and feed them into the final-profile analysis; fabricate the lengthened members to revised drawings and compare node levels with predictions segment by segment during erection, finally checking against the design road profile.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b003-v13-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"纜長固定時 dS = (1 − 8n²/3)·dl + (16f/(3l))·df = 0，故 df = −dl·(1 − 8n²/3)·3l/(16f)。取 n = 0.1、l = 1,991 m、f = 199.1 m、dl = 0.8 m：df = −0.8×0.973×1.875 ≈ −1.46 m。不可伸長假設高估了垂度變化；實際張力增加使主纜彈性伸長、塔頂也有變位，公開報告值約 1.3 m。n 為教學假設。","textEn":"With fixed cable length dS = (1 − 8n²/3)·dl + (16f/(3l))·df = 0, so df = −dl·(1 − 8n²/3)·3l/(16f). With n = 0.1, l = 1,991 m, f = 199.1 m and dl = 0.8 m: df = −0.8×0.973×1.875 ≈ −1.46 m. The inextensible assumption overestimates the change; the extra tension stretches the cable elastically and the tower tops also move, and the published value is about 1.3 m. n is a teaching assumption.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"依「跨徑變化後的垂度與桁段修正」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Sag change and truss correction after the span grew\", which statement holds?","options":["主纜外面有鍍鋅纏絲與塗裝，內部就不會潮濕。","纜長固定時 dS = (1 − 8n²/3)·dl + (16f/(3l))·df = 0，故 df = −dl·(1 − 8n²/3)·3l/(16f)。","桁架加勁梁很深很重，所以不會發生顫振。"],"optionsEn":["With galvanised wrapping and paint outside, the cable interior cannot get wet.","With fixed cable length dS = (1 − 8n²/3)·dl + (16f/(3l))·df = 0, so df = −dl·(1 − 8n²/3)·3l/(16f).","A truss stiffening girder is deep and heavy, so it cannot flutter."],"answer":1,"explanation":"纜長固定時 dS = (1 − 8n²/3)·dl + (16f/(3l))·df = 0，故 df = −dl·(1 − 8n²/3)·3l/(16f)。 重算時請保留單位。","explanationEn":"With fixed cable length dS = (1 − 8n²/3)·dl + (16f/(3l))·df = 0, so df = −dl·(1 − 8n²/3)·3l/(16f). Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":34},{"id":"b003-v13-23","title":"跨徑變化後的垂度與桁段修正：試驗與驗證","titleEn":"Sag change and truss correction after the span grew: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「1995 年地震後桁段加長」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Post-1995 truss lengthening” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"事件後以 GPS 與精密測量重新建立各基礎與塔頂座標，量測主纜各跨垂度與索鞍位置，回饋到完工線形分析；加長的桁段在工廠以修正圖說製造，架設中逐段比對節點高程與預測值，最終與設計車道縱斷面比較。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"After the event re-establish coordinates of every foundation and tower top by GPS and precise survey, measure cable sag in each span and saddle positions, and feed them into the final-profile analysis; fabricate the lengthened members to revised drawings and compare node levels with predictions segment by segment during erection, finally checking against the design road profile. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：大型懸索橋施工期間應持續保存基礎、塔頂與主纜的測量基準與時間序列，並預先規劃「事件後重新測量—重算線形—修正未製構件」的決策流程與核准層級；修正圖說須由設計者簽認後才可投料。","observationEn":"Site practice: During construction of a major suspension bridge keep survey baselines and time series for foundations, tower tops and cables, and plan in advance the decision path of post-event survey, profile re-analysis and revision of unfabricated members with its approval levels; revised drawings must be signed by the designer before steel is cut.","failure":"注意干擾：若沿用原設計長度製造加勁桁，桁段與吊索幾何不相容，合龍時會出現強迫的拉壓力與伸縮縫錯位；未重新檢核塔底應力與主纜張力，也可能低估地震造成的永久附加應力（公開論文報告塔底附加應力最大約 18.2 N/mm²）。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Fabricating the truss to the original lengths would make segments incompatible with hanger geometry, forcing tension and compression at closure and misaligning expansion joints; skipping a re-check of tower-base stress and cable tension could miss the permanent added stress from the quake (the paper reports up to about 18.2 N/mm² at the tower base). A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b003-v13-23-k1","title":"驗證方法","titleEn":"Verification method","text":"事件後以 GPS 與精密測量重新建立各基礎與塔頂座標，量測主纜各跨垂度與索鞍位置，回饋到完工線形分析；加長的桁段在工廠以修正圖說製造，架設中逐段比對節點高程與預測值，最終與設計車道縱斷面比較。","textEn":"After the event re-establish coordinates of every foundation and tower top by GPS and precise survey, measure cable sag in each span and saddle positions, and feed them into the final-profile analysis; fabricate the lengthened members to revised drawings and compare node levels with predictions segment by segment during erection, finally checking against the design road profile.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-23-k2","title":"現場實務","titleEn":"Site practice","text":"大型懸索橋施工期間應持續保存基礎、塔頂與主纜的測量基準與時間序列，並預先規劃「事件後重新測量—重算線形—修正未製構件」的決策流程與核准層級；修正圖說須由設計者簽認後才可投料。","textEn":"During construction of a major suspension bridge keep survey baselines and time series for foundations, tower tops and cables, and plan in advance the decision path of post-event survey, profile re-analysis and revision of unfabricated members with its approval levels; revised drawings must be signed by the designer before steel is cut.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"要驗證「跨徑變化後的垂度與桁段修正」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Sag change and truss correction after the span grew\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","鋼絲強度越高，主纜就越不需要防蝕。","事件後以 GPS 與精密測量重新建立各基礎與塔頂座標，量測主纜各跨垂度與索鞍位置，回饋到完工線形分析。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","The stronger the wire, the less corrosion protection the cable needs.","After the event re-establish coordinates of every foundation and tower top by GPS and precise survey, measure cable sag in each span and saddle positions, and feed them into the final-profile analysis."],"answer":2,"explanation":"事件後以 GPS 與精密測量重新建立各基礎與塔頂座標，量測主纜各跨垂度與索鞍位置，回饋到完工線形分析；加長的桁段在工廠以修正圖說製造，架設中逐段比對節點高程與預測值，最終與設計車道縱斷面比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"After the event re-establish coordinates of every foundation and tower top by GPS and precise survey, measure cable sag in each span and saddle positions, and feed them into the final-profile analysis; fabricate the lengthened members to revised drawings and compare node levels with predictions segment by segment during erection, finally checking against the design road profile. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":35},{"id":"b003-v13-24","title":"跨徑變化後的垂度與桁段修正：失效診斷","titleEn":"Sag change and truss correction after the span grew: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-23"],"objective":"從症狀倒推「1995 年地震後桁段加長」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Post-1995 truss lengthening” and propose discriminating checks, corrective actions and prevention.","instruction":"若沿用原設計長度製造加勁桁，桁段與吊索幾何不相容，合龍時會出現強迫的拉壓力與伸縮縫錯位；未重新檢核塔底應力與主纜張力，也可能低估地震造成的永久附加應力（公開論文報告塔底附加應力最大約 18.2 N/mm²）。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Fabricating the truss to the original lengths would make segments incompatible with hanger geometry, forcing tension and compression at closure and misaligning expansion joints; skipping a re-check of tower-base stress and cable tension could miss the permanent added stress from the quake (the paper reports up to about 18.2 N/mm² at the tower base). Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：公開論文指出中央跨垂度約減少 1.3 m，主纜張力增加約為原設計最大張力的 0.6%，仍在容許範圍內。","observationEn":"Link to the mechanism: The published paper reports a centre-span sag reduction of about 1.3 m and an extra cable tension of about 0.6% of the original maximum, within the allowable.","failure":"誤判風險：若相信「地震後只要把橋塔推回原位，就能維持原設計線形。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"After an earthquake you simply push the towers back to restore the design profile.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b003-v13-24-k1","title":"失效模式","titleEn":"Failure mode","text":"若沿用原設計長度製造加勁桁，桁段與吊索幾何不相容，合龍時會出現強迫的拉壓力與伸縮縫錯位；未重新檢核塔底應力與主纜張力，也可能低估地震造成的永久附加應力（公開論文報告塔底附加應力最大約 18.2 N/mm²）。","textEn":"Fabricating the truss to the original lengths would make segments incompatible with hanger geometry, forcing tension and compression at closure and misaligning expansion joints; skipping a re-check of tower-base stress and cable tension could miss the permanent added stress from the quake (the paper reports up to about 18.2 N/mm² at the tower base).","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"在「跨徑變化後的垂度與桁段修正」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Sag change and truss correction after the span grew\" shows distress, which diagnosis is most reasonable?","options":["若沿用原設計長度製造加勁桁，桁段與吊索幾何不相容，合龍時會出現強迫的拉壓力與伸縮縫錯位。","只要結構還沒倒，就代表安全餘裕仍然足夠。","全橋模型的風速必須和實橋一樣，試驗才有意義。"],"optionsEn":["Fabricating the truss to the original lengths would make segments incompatible with hanger geometry, forcing tension and compression at closure and misaligning expansion joints.","As long as the structure is still standing, its safety margin must still be adequate.","A full-bridge model is only meaningful if tested at the same wind speed as the real bridge."],"answer":0,"explanation":"若沿用原設計長度製造加勁桁，桁段與吊索幾何不相容，合龍時會出現強迫的拉壓力與伸縮縫錯位；未重新檢核塔底應力與主纜張力，也可能低估地震造成的永久附加應力（公開論文報告塔底附加應力最大約 18.2 N/mm²）。 需以量測區分可能原因。","explanationEn":"Fabricating the truss to the original lengths would make segments incompatible with hanger geometry, forcing tension and compression at closure and misaligning expansion joints; skipping a re-check of tower-base stress and cable tension could miss the permanent added stress from the quake (the paper reports up to about 18.2 N/mm² at the tower base). Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":36}],"order":6},{"id":"b003-v13-s4","title":"試驗、量測與監測驗證","titleEn":"Testing, measurement and monitoring","description":"本階段聚焦「全橋模型試驗與颱風實測比對」與「長吊索尾流振動與螺旋纏絲」：先建立傳力機制與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Full-bridge model tests versus typhoon records\" and \"Long-hanger wake vibration and helical wire\": build the load path and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b003-v13-25","title":"全橋模型試驗與颱風實測比對：機制與傳力路徑","titleEn":"Full-bridge model tests versus typhoon records: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-24"],"objective":"說明「全橋氣彈模型與颱風實測」如何影響明石海峽大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “Full model and typhoon records” governs force, deformation or durability in “Akashi Kaikyo Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"斷面模型只能代表二維流場，懸索橋的顫振與抖振卻牽涉多個三維模態、主纜與塔的氣動力，以及沿跨長變化的紊流。明石海峽大橋因此在大型風洞中做全橋氣彈模型試驗，模型需同時滿足幾何、質量、勁度與重力相似，以 Froude 相似律換算風速與頻率；完工後研究者再以颱風期間的風速計、加速度計與 GPS 實測，比對抖振位移與模態阻尼，驗證設計假設。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「全橋氣彈模型與颱風實測」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A section model represents only two-dimensional flow, while flutter and buffeting of a suspension bridge involve several three-dimensional modes, aerodynamic forces on cables and towers, and turbulence that varies along the span. Akashi Kaikyo was therefore tested with a full aeroelastic model in a large wind tunnel, which must reproduce geometry, mass, stiffness and gravity together, with wind speed and frequency scaled by Froude similarity; after completion researchers compared buffeting displacement and modal damping with anemometer, accelerometer and GPS records from typhoons to validate the design assumptions. Mentor task: draw a free-body or load-path diagram showing how loads pass through “Full model and typhoon records” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：Froude 相似：長度比 λ = 1/100 時，風速比 √λ = 1/10、頻率比 1/√λ = 10、單位長質量比 λ² = 1/10,000。","observationEn":"Order-of-magnitude cue: Froude similarity: with length scale λ = 1/100, velocity scales by √λ = 1/10, frequency by 1/√λ = 10 and mass per length by λ² = 1/10,000.","failure":"常見誤解：「全橋模型的風速必須和實橋一樣，試驗才有意義。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A full-bridge model is only meaningful if tested at the same wind speed as the real bridge.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「全橋氣彈模型與颱風實測」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “Full model and typhoon records”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b003-v13-25-k1","title":"全橋模型試驗與颱風實測比對","titleEn":"Full-bridge model tests versus typhoon records","text":"斷面模型只能代表二維流場，懸索橋的顫振與抖振卻牽涉多個三維模態、主纜與塔的氣動力，以及沿跨長變化的紊流。明石海峽大橋因此在大型風洞中做全橋氣彈模型試驗，模型需同時滿足幾何、質量、勁度與重力相似，以 Froude 相似律換算風速與頻率；完工後研究者再以颱風期間的風速計、加速度計與 GPS 實測，比對抖振位移與模態阻尼，驗證設計假設。","textEn":"A section model represents only two-dimensional flow, while flutter and buffeting of a suspension bridge involve several three-dimensional modes, aerodynamic forces on cables and towers, and turbulence that varies along the span. Akashi Kaikyo was therefore tested with a full aeroelastic model in a large wind tunnel, which must reproduce geometry, mass, stiffness and gravity together, with wind speed and frequency scaled by Froude similarity; after completion researchers compared buffeting displacement and modal damping with anemometer, accelerometer and GPS records from typhoons to validate the design assumptions.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：全橋模型的風速必須和實橋一樣，試驗才有意義。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A full-bridge model is only meaningful if tested at the same wind speed as the real bridge. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"關於「全橋模型試驗與颱風實測比對」，下列哪一項敘述正確？","questionEn":"Which statement about \"Full-bridge model tests versus typhoon records\" is correct?","options":["全橋模型的風速必須和實橋一樣，試驗才有意義。","斷面模型只能代表二維流場，懸索橋的顫振與抖振卻牽涉多個三維模態、主纜與塔的氣動力，以及沿跨長變化的紊流。","只要吊索間距大於 5 倍直徑，就不會有尾流振動。"],"optionsEn":["A full-bridge model is only meaningful if tested at the same wind speed as the real bridge.","A section model represents only two-dimensional flow, while flutter and buffeting of a suspension bridge involve several three-dimensional modes, aerodynamic forces on cables and towers, and turbulence that varies along the span.","Hangers spaced more than five diameters apart can never suffer wake vibration."],"answer":1,"explanation":"斷面模型只能代表二維流場，懸索橋的顫振與抖振卻牽涉多個三維模態、主纜與塔的氣動力，以及沿跨長變化的紊流。 其餘選項是常見誤解。","explanationEn":"A section model represents only two-dimensional flow, while flutter and buffeting of a suspension bridge involve several three-dimensional modes, aerodynamic forces on cables and towers, and turbulence that varies along the span. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":37},{"id":"b003-v13-26","title":"全橋模型試驗與颱風實測比對：定量估算","titleEn":"Full-bridge model tests versus typhoon records: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-25"],"objective":"以數值模型估算「全橋氣彈模型與颱風實測」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Full model and typhoon records” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：Froude 相似：長度比 λ = 1/100 時，風速比 √λ = 1/10、頻率比 1/√λ = 10、單位長質量比 λ² = 1/10,000。實橋 80 m/s 對應模型 8 m/s；0.065 Hz 對應 0.65 Hz；44,000 kg/m 對應 4.4 kg/m；全長 3,911 m 的模型約 39 m。數值為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Froude similarity: with length scale λ = 1/100, velocity scales by √λ = 1/10, frequency by 1/√λ = 10 and mass per length by λ² = 1/10,000. A full-scale 80 m/s maps to 8 m/s in the model, 0.065 Hz to 0.65 Hz, 44,000 kg/m to 4.4 kg/m, and the 3,911 m bridge becomes a model about 39 m long. Values are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：模型先做自由振動試驗確認各模態頻率與阻尼符合相似要求，再在均勻流與紊流中逐級提高風速記錄位移與發散點；實橋比對時把颱風紀錄依平均風速分段，以頻譜辨識模態頻率與阻尼，並比較量測抖振位移與預測值的比值。","observationEn":"How to cross-check: First run free-vibration tests on the model to confirm modal frequencies and damping meet similarity, then raise wind speed step by step in smooth and turbulent flow, recording displacement and divergence; for full-scale comparison bin typhoon records by mean wind speed, identify frequencies and damping from spectra, and compare the ratio of measured to predicted buffeting displacement.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b003-v13-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"Froude 相似：長度比 λ = 1/100 時，風速比 √λ = 1/10、頻率比 1/√λ = 10、單位長質量比 λ² = 1/10,000。實橋 80 m/s 對應模型 8 m/s；0.065 Hz 對應 0.65 Hz；44,000 kg/m 對應 4.4 kg/m；全長 3,911 m 的模型約 39 m。數值為教學假設。","textEn":"Froude similarity: with length scale λ = 1/100, velocity scales by √λ = 1/10, frequency by 1/√λ = 10 and mass per length by λ² = 1/10,000. A full-scale 80 m/s maps to 8 m/s in the model, 0.065 Hz to 0.65 Hz, 44,000 kg/m to 4.4 kg/m, and the 3,911 m bridge becomes a model about 39 m long. Values are teaching assumptions.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"依「全橋模型試驗與颱風實測比對」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Full-bridge model tests versus typhoon records\", which statement holds?","options":["減振裝置維護得越頻繁，橋梁一定越安全。","懸索橋很柔，所以地震對它幾乎沒有影響。","Froude 相似：長度比 λ = 1/100 時，風速比 √λ = 1/10、頻率比 1/√λ = 10、單位長質量比 λ² = 1/10,000。"],"optionsEn":["The more often dampers are serviced, the safer the bridge must be.","A suspension bridge is so flexible that earthquakes hardly affect it.","Froude similarity: with length scale λ = 1/100, velocity scales by √λ = 1/10, frequency by 1/√λ = 10 and mass per length by λ² = 1/10,000."],"answer":2,"explanation":"Froude 相似：長度比 λ = 1/100 時，風速比 √λ = 1/10、頻率比 1/√λ = 10、單位長質量比 λ² = 1/10,000。 重算時請保留單位。","explanationEn":"Froude similarity: with length scale λ = 1/100, velocity scales by √λ = 1/10, frequency by 1/√λ = 10 and mass per length by λ² = 1/10,000. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":38},{"id":"b003-v13-27","title":"全橋模型試驗與颱風實測比對：試驗與驗證","titleEn":"Full-bridge model tests versus typhoon records: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「全橋氣彈模型與颱風實測」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Full model and typhoon records” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"模型先做自由振動試驗確認各模態頻率與阻尼符合相似要求，再在均勻流與紊流中逐級提高風速記錄位移與發散點；實橋比對時把颱風紀錄依平均風速分段，以頻譜辨識模態頻率與阻尼，並比較量測抖振位移與預測值的比值。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"First run free-vibration tests on the model to confirm modal frequencies and damping meet similarity, then raise wind speed step by step in smooth and turbulent flow, recording displacement and divergence; for full-scale comparison bin typhoon records by mean wind speed, identify frequencies and damping from spectra, and compare the ratio of measured to predicted buffeting displacement. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：試驗計畫應明列相似律、模型頻率與阻尼的允差、紊流條件與試驗風攻角；完工監測報告要附原始資料與處理參數，讓日後研究者能以新方法重新分析並與風洞結果比較。","observationEn":"Site practice: The test plan must state the similarity law, tolerances on model frequency and damping, turbulence conditions and angles of attack; completion monitoring reports should include raw data and processing parameters so later researchers can reanalyse them and compare with the tunnel results.","failure":"注意干擾：模型阻尼過高或質量分布不符，會使顫振風速被高估；紊流強度與積分尺度若與海峽實況不同，抖振預測可能偏差。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Excess damping or wrong mass distribution in the model overestimates the flutter speed; turbulence intensity and integral scale unlike the strait's can bias buffeting predictions. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b003-v13-27-k1","title":"驗證方法","titleEn":"Verification method","text":"模型先做自由振動試驗確認各模態頻率與阻尼符合相似要求，再在均勻流與紊流中逐級提高風速記錄位移與發散點；實橋比對時把颱風紀錄依平均風速分段，以頻譜辨識模態頻率與阻尼，並比較量測抖振位移與預測值的比值。","textEn":"First run free-vibration tests on the model to confirm modal frequencies and damping meet similarity, then raise wind speed step by step in smooth and turbulent flow, recording displacement and divergence; for full-scale comparison bin typhoon records by mean wind speed, identify frequencies and damping from spectra, and compare the ratio of measured to predicted buffeting displacement.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-27-k2","title":"現場實務","titleEn":"Site practice","text":"試驗計畫應明列相似律、模型頻率與阻尼的允差、紊流條件與試驗風攻角；完工監測報告要附原始資料與處理參數，讓日後研究者能以新方法重新分析並與風洞結果比較。","textEn":"The test plan must state the similarity law, tolerances on model frequency and damping, turbulence conditions and angles of attack; completion monitoring reports should include raw data and processing parameters so later researchers can reanalyse them and compare with the tunnel results.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"要驗證「全橋模型試驗與颱風實測比對」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Full-bridge model tests versus typhoon records\"?","options":["模型先做自由振動試驗確認各模態頻率與阻尼符合相似要求，再在均勻流與紊流中逐級提高風速記錄位移與發散點。","量測時不必記錄溫度、日照、風與施工荷重，因為它們不會影響結果。","水中混凝土只要配比強度夠高，澆置方式不影響品質。"],"optionsEn":["First run free-vibration tests on the model to confirm modal frequencies and damping meet similarity, then raise wind speed step by step in smooth and turbulent flow, recording displacement and divergence.","Temperature, sunshine, wind and construction loads need not be recorded because they cannot affect the result.","If the underwater mix is strong enough, the placing method does not affect quality."],"answer":0,"explanation":"模型先做自由振動試驗確認各模態頻率與阻尼符合相似要求，再在均勻流與紊流中逐級提高風速記錄位移與發散點；實橋比對時把颱風紀錄依平均風速分段，以頻譜辨識模態頻率與阻尼，並比較量測抖振位移與預測值的比值。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"First run free-vibration tests on the model to confirm modal frequencies and damping meet similarity, then raise wind speed step by step in smooth and turbulent flow, recording displacement and divergence; for full-scale comparison bin typhoon records by mean wind speed, identify frequencies and damping from spectra, and compare the ratio of measured to predicted buffeting displacement. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":39},{"id":"b003-v13-28","title":"全橋模型試驗與颱風實測比對：失效診斷","titleEn":"Full-bridge model tests versus typhoon records: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-27"],"objective":"從症狀倒推「全橋氣彈模型與颱風實測」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Full model and typhoon records” and propose discriminating checks, corrective actions and prevention.","instruction":"模型阻尼過高或質量分布不符，會使顫振風速被高估；紊流強度與積分尺度若與海峽實況不同，抖振預測可能偏差。實測時若 GPS 多路徑誤差或風速計受橋體遮蔽未修正，也會錯誤地「驗證」或否定設計。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Excess damping or wrong mass distribution in the model overestimates the flutter speed; turbulence intensity and integral scale unlike the strait's can bias buffeting predictions. In field data, uncorrected GPS multipath or anemometers shielded by the deck can falsely confirm or reject the design. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：明石海峽大橋因此在大型風洞中做全橋氣彈模型試驗，模型需同時滿足幾何、質量、勁度與重力相似，以 Froude 相似律換算風速與頻率；完工後研究者再以颱風期間的風速計、加速度計與 GPS 實測，比對抖振位移與模態阻尼，驗證設計假設。","observationEn":"Link to the mechanism: Akashi Kaikyo was therefore tested with a full aeroelastic model in a large wind tunnel, which must reproduce geometry, mass, stiffness and gravity together, with wind speed and frequency scaled by Froude similarity; after completion researchers compared buffeting displacement and modal damping with anemometer, accelerometer and GPS records from typhoons to validate the design assumptions.","failure":"誤判風險：若相信「全橋模型的風速必須和實橋一樣，試驗才有意義。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A full-bridge model is only meaningful if tested at the same wind speed as the real bridge.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b003-v13-28-k1","title":"失效模式","titleEn":"Failure mode","text":"模型阻尼過高或質量分布不符，會使顫振風速被高估；紊流強度與積分尺度若與海峽實況不同，抖振預測可能偏差。實測時若 GPS 多路徑誤差或風速計受橋體遮蔽未修正，也會錯誤地「驗證」或否定設計。","textEn":"Excess damping or wrong mass distribution in the model overestimates the flutter speed; turbulence intensity and integral scale unlike the strait's can bias buffeting predictions. In field data, uncorrected GPS multipath or anemometers shielded by the deck can falsely confirm or reject the design.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"在「全橋模型試驗與颱風實測比對」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Full-bridge model tests versus typhoon records\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","模型阻尼過高或質量分布不符，會使顫振風速被高估；紊流強度與積分尺度若與海峽實況不同，抖振預測可能偏差。","只要吊索間距大於 5 倍直徑，就不會有尾流振動。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Excess damping or wrong mass distribution in the model overestimates the flutter speed.","Hangers spaced more than five diameters apart can never suffer wake vibration."],"answer":1,"explanation":"模型阻尼過高或質量分布不符，會使顫振風速被高估；紊流強度與積分尺度若與海峽實況不同，抖振預測可能偏差。 需以量測區分可能原因。","explanationEn":"Excess damping or wrong mass distribution in the model overestimates the flutter speed; turbulence intensity and integral scale unlike the strait's can bias buffeting predictions. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":40},{"id":"b003-v13-29","title":"長吊索尾流振動與螺旋纏絲：機制與傳力路徑","titleEn":"Long-hanger wake vibration and helical wire: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-28"],"objective":"說明「長吊索尾流振動」如何影響明石海峽大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “Long-hanger wake vibration” governs force, deformation or durability in “Akashi Kaikyo Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"明石海峽大橋部分吊索長度超過 200 m，每個索夾處有並排的平行鋼絲吊索，間距約為吊索直徑的 9 倍。完工後觀察到在約 20 m/s 的風中，背風側吊索因位於迎風吊索的尾流中而大幅振動；過去一般認為這類尾流馳振只在間距小於約 5 倍直徑時發生。風洞試驗顯示，在吊索表面螺旋纏繞直徑 10 mm 的鋼絲可打亂尾流與表面分離，降低振動，營運單位並開發了纏絲機械施作。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「長吊索尾流振動」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Some Akashi Kaikyo hangers exceed 200 m, and at each cable band parallel-wire hanger ropes run side by side at a spacing of about nine rope diameters. After completion the leeward ropes were seen vibrating strongly in winds of about 20 m/s because they sat in the wake of the windward ropes; such wake galloping had previously been thought to occur only at spacings below about five diameters. Wind-tunnel tests showed that winding 10 mm wire helically around the rope disrupts the wake and surface separation and reduces the vibration, and the operator developed a winding machine to install it. Mentor task: draw a free-body or load-path diagram showing how loads pass through “Long-hanger wake vibration” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：弦頻率 f₁ = (1/2L)·√(T/m)。","observationEn":"Order-of-magnitude cue: String frequency f₁ = (1/2L)·√(T/m).","failure":"常見誤解：「只要吊索間距大於 5 倍直徑，就不會有尾流振動。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Hangers spaced more than five diameters apart can never suffer wake vibration.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「長吊索尾流振動」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “Long-hanger wake vibration”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b003-v13-29-k1","title":"長吊索尾流振動與螺旋纏絲","titleEn":"Long-hanger wake vibration and helical wire","text":"明石海峽大橋部分吊索長度超過 200 m，每個索夾處有並排的平行鋼絲吊索，間距約為吊索直徑的 9 倍。完工後觀察到在約 20 m/s 的風中，背風側吊索因位於迎風吊索的尾流中而大幅振動；過去一般認為這類尾流馳振只在間距小於約 5 倍直徑時發生。","textEn":"Some Akashi Kaikyo hangers exceed 200 m, and at each cable band parallel-wire hanger ropes run side by side at a spacing of about nine rope diameters. After completion the leeward ropes were seen vibrating strongly in winds of about 20 m/s because they sat in the wake of the windward ropes; such wake galloping had previously been thought to occur only at spacings below about five diameters.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要吊索間距大於 5 倍直徑，就不會有尾流振動。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Hangers spaced more than five diameters apart can never suffer wake vibration. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"關於「長吊索尾流振動與螺旋纏絲」，下列哪一項敘述正確？","questionEn":"Which statement about \"Long-hanger wake vibration and helical wire\" is correct?","options":["只要吊索間距大於 5 倍直徑，就不會有尾流振動。","主纜外面有鍍鋅纏絲與塗裝，內部就不會潮濕。","明石海峽大橋部分吊索長度超過 200 m，每個索夾處有並排的平行鋼絲吊索，間距約為吊索直徑的 9 倍。"],"optionsEn":["Hangers spaced more than five diameters apart can never suffer wake vibration.","With galvanised wrapping and paint outside, the cable interior cannot get wet.","Some Akashi Kaikyo hangers exceed 200 m, and at each cable band parallel-wire hanger ropes run side by side at a spacing of about nine rope diameters."],"answer":2,"explanation":"明石海峽大橋部分吊索長度超過 200 m，每個索夾處有並排的平行鋼絲吊索，間距約為吊索直徑的 9 倍。 其餘選項是常見誤解。","explanationEn":"Some Akashi Kaikyo hangers exceed 200 m, and at each cable band parallel-wire hanger ropes run side by side at a spacing of about nine rope diameters. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":41},{"id":"b003-v13-30","title":"長吊索尾流振動與螺旋纏絲：定量估算","titleEn":"Long-hanger wake vibration and helical wire: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-29"],"objective":"以數值模型估算「長吊索尾流振動」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Long-hanger wake vibration” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：弦頻率 f₁ = (1/2L)·√(T/m)。取 L = 200 m、T = 1.6 MN、m = 40 kg/m：√(T/m) = 200 m/s，f₁ = 200/400 = 0.5 Hz。直徑 D = 0.09 m、風速 20 m/s 時折減風速 U/(f·D) = 20/(0.5×0.09) ≈ 444，遠高於渦振範圍，屬尾流馳振區；間距 9D ≈ 0.81 m。數值為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: String frequency f₁ = (1/2L)·√(T/m). With L = 200 m, T = 1.6 MN and m = 40 kg/m: √(T/m) = 200 m/s and f₁ = 200/400 = 0.5 Hz. With D = 0.09 m at 20 m/s the reduced velocity U/(f·D) = 20/(0.5×0.09) ≈ 444, far above the vortex range and in the wake-galloping regime; the spacing 9D ≈ 0.81 m. Values are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在代表性吊索上安裝加速度計與風速風向計，記錄振幅與風向、風速的關係，辨識振動只出現在特定風向與背風索；風洞中以成對索段試驗有無纏絲、不同纏繞節距的反應，選定方案後再在實橋試裝並比較前後振幅。","observationEn":"How to cross-check: Fit accelerometers and anemometers to representative hangers and relate amplitude to wind speed and direction, confirming that vibration appears only for certain directions and on the leeward rope; in the wind tunnel test paired rope segments with and without wire and with different pitches, then trial-fit the chosen scheme on the bridge and compare amplitudes before and after.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b003-v13-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"弦頻率 f₁ = (1/2L)·√(T/m)。取 L = 200 m、T = 1.6 MN、m = 40 kg/m：√(T/m) = 200 m/s，f₁ = 200/400 = 0.5 Hz。直徑 D = 0.09 m、風速 20 m/s 時折減風速 U/(f·D) = 20/(0.5×0.09) ≈ 444，遠高於渦振範圍，屬尾流馳振區；間距 9D ≈ 0.81 m。數值為教學假設。","textEn":"String frequency f₁ = (1/2L)·√(T/m). With L = 200 m, T = 1.6 MN and m = 40 kg/m: √(T/m) = 200 m/s and f₁ = 200/400 = 0.5 Hz. With D = 0.09 m at 20 m/s the reduced velocity U/(f·D) = 20/(0.5×0.09) ≈ 444, far above the vortex range and in the wake-galloping regime; the spacing 9D ≈ 0.81 m. Values are teaching assumptions.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"依「長吊索尾流振動與螺旋纏絲」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Long-hanger wake vibration and helical wire\", which statement holds?","options":["弦頻率 f₁ = (1/2L)·√(T/m)。","桁架加勁梁很深很重，所以不會發生顫振。","鋼絲強度越高，主纜就越不需要防蝕。"],"optionsEn":["String frequency f₁ = (1/2L)·√(T/m).","A truss stiffening girder is deep and heavy, so it cannot flutter.","The stronger the wire, the less corrosion protection the cable needs."],"answer":0,"explanation":"弦頻率 f₁ = (1/2L)·√(T/m)。 重算時請保留單位。","explanationEn":"String frequency f₁ = (1/2L)·√(T/m). Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":42},{"id":"b003-v13-31","title":"長吊索尾流振動與螺旋纏絲：試驗與驗證","titleEn":"Long-hanger wake vibration and helical wire: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「長吊索尾流振動」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Long-hanger wake vibration” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在代表性吊索上安裝加速度計與風速風向計，記錄振幅與風向、風速的關係，辨識振動只出現在特定風向與背風索；風洞中以成對索段試驗有無纏絲、不同纏繞節距的反應，選定方案後再在實橋試裝並比較前後振幅。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Fit accelerometers and anemometers to representative hangers and relate amplitude to wind speed and direction, confirming that vibration appears only for certain directions and on the leeward rope; in the wind tunnel test paired rope segments with and without wire and with different pitches, then trial-fit the chosen scheme on the bridge and compare amplitudes before and after. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：長吊索的振動觀測應從完工初期就納入監測計畫，特定風向的異常振動要記錄並回報設計者；纏絲、阻尼器或連結件等對策必須先經風洞或試裝驗證，並確認不妨礙日後的磁通檢測。","observationEn":"Site practice: Observation of long-hanger vibration should be in the monitoring plan from the first year, recording and reporting unusual vibration in particular wind directions; wire winding, dampers or ties must be proven by wind-tunnel tests or trial fitting and must not obstruct later magnetic-flux inspection.","failure":"注意干擾：長吊索反覆大振幅擺動會使索夾出口與錨頭處彎曲應力集中、鋼絲磨損與疲勞，兩索相互碰撞也會損傷護套與防蝕層，讓水分進入吊索內部。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Repeated large swings of long hangers concentrate bending stress where the rope exits the cable band and at its socket, wearing and fatiguing the wires; ropes striking each other also damage sheathing and corrosion protection and let water into the rope. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b003-v13-31-k1","title":"驗證方法","titleEn":"Verification method","text":"在代表性吊索上安裝加速度計與風速風向計，記錄振幅與風向、風速的關係，辨識振動只出現在特定風向與背風索；風洞中以成對索段試驗有無纏絲、不同纏繞節距的反應，選定方案後再在實橋試裝並比較前後振幅。","textEn":"Fit accelerometers and anemometers to representative hangers and relate amplitude to wind speed and direction, confirming that vibration appears only for certain directions and on the leeward rope; in the wind tunnel test paired rope segments with and without wire and with different pitches, then trial-fit the chosen scheme on the bridge and compare amplitudes before and after.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-31-k2","title":"現場實務","titleEn":"Site practice","text":"長吊索的振動觀測應從完工初期就納入監測計畫，特定風向的異常振動要記錄並回報設計者；纏絲、阻尼器或連結件等對策必須先經風洞或試裝驗證，並確認不妨礙日後的磁通檢測。","textEn":"Observation of long-hanger vibration should be in the monitoring plan from the first year, recording and reporting unusual vibration in particular wind directions; wire winding, dampers or ties must be proven by wind-tunnel tests or trial fitting and must not obstruct later magnetic-flux inspection.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"要驗證「長吊索尾流振動與螺旋纏絲」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Long-hanger wake vibration and helical wire\"?","options":["沿用另一座橋或另一棟建築的量測結果，就可視為本工程已完成驗證。","在代表性吊索上安裝加速度計與風速風向計，記錄振幅與風向、風速的關係，辨識振動只出現在特定風向與背風索。","索股垂度只要白天量一次，誤差幾公分不影響主纜受力。"],"optionsEn":["Reusing results from another bridge or building counts as verifying this structure.","Fit accelerometers and anemometers to representative hangers and relate amplitude to wind speed and direction, confirming that vibration appears only for certain directions and on the leeward rope.","Measuring strand sag once in daytime is fine; a few centimetres of error do not affect cable forces."],"answer":1,"explanation":"在代表性吊索上安裝加速度計與風速風向計，記錄振幅與風向、風速的關係，辨識振動只出現在特定風向與背風索；風洞中以成對索段試驗有無纏絲、不同纏繞節距的反應，選定方案後再在實橋試裝並比較前後振幅。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Fit accelerometers and anemometers to representative hangers and relate amplitude to wind speed and direction, confirming that vibration appears only for certain directions and on the leeward rope; in the wind tunnel test paired rope segments with and without wire and with different pitches, then trial-fit the chosen scheme on the bridge and compare amplitudes before and after. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":43},{"id":"b003-v13-32","title":"長吊索尾流振動與螺旋纏絲：失效診斷","titleEn":"Long-hanger wake vibration and helical wire: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-31"],"objective":"從症狀倒推「長吊索尾流振動」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Long-hanger wake vibration” and propose discriminating checks, corrective actions and prevention.","instruction":"長吊索反覆大振幅擺動會使索夾出口與錨頭處彎曲應力集中、鋼絲磨損與疲勞，兩索相互碰撞也會損傷護套與防蝕層，讓水分進入吊索內部。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Repeated large swings of long hangers concentrate bending stress where the rope exits the cable band and at its socket, wearing and fatiguing the wires; ropes striking each other also damage sheathing and corrosion protection and let water into the rope. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：風洞試驗顯示，在吊索表面螺旋纏繞直徑 10 mm 的鋼絲可打亂尾流與表面分離，降低振動，營運單位並開發了纏絲機械施作。","observationEn":"Link to the mechanism: Wind-tunnel tests showed that winding 10 mm wire helically around the rope disrupts the wake and surface separation and reduces the vibration, and the operator developed a winding machine to install it.","failure":"誤判風險：若相信「只要吊索間距大於 5 倍直徑，就不會有尾流振動。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Hangers spaced more than five diameters apart can never suffer wake vibration.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b003-v13-32-k1","title":"失效模式","titleEn":"Failure mode","text":"長吊索反覆大振幅擺動會使索夾出口與錨頭處彎曲應力集中、鋼絲磨損與疲勞，兩索相互碰撞也會損傷護套與防蝕層，讓水分進入吊索內部。","textEn":"Repeated large swings of long hangers concentrate bending stress where the rope exits the cable band and at its socket, wearing and fatiguing the wires; ropes striking each other also damage sheathing and corrosion protection and let water into the rope.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"在「長吊索尾流振動與螺旋纏絲」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Long-hanger wake vibration and helical wire\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","主纜外面有鍍鋅纏絲與塗裝，內部就不會潮濕。","長吊索反覆大振幅擺動會使索夾出口與錨頭處彎曲應力集中、鋼絲磨損與疲勞，兩索相互碰撞也會損傷護套與防蝕層，讓水分進入吊索內部。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","With galvanised wrapping and paint outside, the cable interior cannot get wet.","Repeated large swings of long hangers concentrate bending stress where the rope exits the cable band and at its socket, wearing and fatiguing the wires."],"answer":2,"explanation":"長吊索反覆大振幅擺動會使索夾出口與錨頭處彎曲應力集中、鋼絲磨損與疲勞，兩索相互碰撞也會損傷護套與防蝕層，讓水分進入吊索內部。 需以量測區分可能原因。","explanationEn":"Repeated large swings of long hangers concentrate bending stress where the rope exits the cable band and at its socket, wearing and fatiguing the wires; ropes striking each other also damage sheathing and corrosion protection and let water into the rope. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":44}],"order":7},{"id":"b003-v13-s5","title":"耐久、維護與工程交接","titleEn":"Durability, maintenance and engineering handoff","description":"本階段聚焦「主纜乾燥空氣的水分收支」與「減振裝置維護與 200 年資產管理」：先建立傳力機制與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Moisture budget of cable dry-air injection\" and \"Damper upkeep and 200-year asset management\": build the load path and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b003-v13-33","title":"主纜乾燥空氣的水分收支：機制與傳力路徑","titleEn":"Moisture budget of cable dry-air injection: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-32"],"objective":"說明「主纜送氣出口濕度」如何影響明石海峽大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “Cable exhaust humidity” governs force, deformation or durability in “Akashi Kaikyo Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"本州四國連絡橋的檢查發現，舊有懸索橋拆開鍍鋅纏絲後鋼絲已有鏽蝕，因此開發了將乾燥空氣送入主纜內部的系統，並以世界首創的形式用於明石海峽大橋與其他懸索橋。管理目標是纜內相對濕度 40%，比會發生腐蝕的約 60% 留有安全餘裕；夏季高濕時另加預冷設備除濕。乾燥空氣沿主纜空隙流動，一路蒸發並帶走殘留水分，最後從排氣口排出，排氣口的濕度就是纜內是否已乾燥的指標。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「主纜送氣出口濕度」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Inspections of older Honshu-Shikoku suspension bridges found rust on wires once the galvanised wrapping was removed, so a system injecting dry air into the main cable was developed and used, as a world first, on Akashi Kaikyo and the other suspension bridges. The management target is 40% relative humidity inside the cable, a margin below the roughly 60% at which corrosion occurs; pre-coolers dehumidify humid summer air. The dry air travels through the cable voids, evaporating and carrying away trapped moisture before leaving at exhaust points, so exhaust humidity is the indicator of whether the cable interior is dry. Mentor task: draw a free-body or load-path diagram showing how loads pass through “Cable exhaust humidity” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：25 °C 飽和水氣密度約 23.0 g/m³。","observationEn":"Order-of-magnitude cue: Saturated vapour density at 25 °C is about 23.0 g/m³.","failure":"常見誤解：「主纜外面有鍍鋅纏絲與塗裝，內部就不會潮濕。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"With galvanised wrapping and paint outside, the cable interior cannot get wet.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「主纜送氣出口濕度」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “Cable exhaust humidity”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b003-v13-33-k1","title":"主纜乾燥空氣的水分收支","titleEn":"Moisture budget of cable dry-air injection","text":"本州四國連絡橋的檢查發現，舊有懸索橋拆開鍍鋅纏絲後鋼絲已有鏽蝕，因此開發了將乾燥空氣送入主纜內部的系統，並以世界首創的形式用於明石海峽大橋與其他懸索橋。管理目標是纜內相對濕度 40%，比會發生腐蝕的約 60% 留有安全餘裕；夏季高濕時另加預冷設備除濕。","textEn":"Inspections of older Honshu-Shikoku suspension bridges found rust on wires once the galvanised wrapping was removed, so a system injecting dry air into the main cable was developed and used, as a world first, on Akashi Kaikyo and the other suspension bridges. The management target is 40% relative humidity inside the cable, a margin below the roughly 60% at which corrosion occurs; pre-coolers dehumidify humid summer air.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：主纜外面有鍍鋅纏絲與塗裝，內部就不會潮濕。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: With galvanised wrapping and paint outside, the cable interior cannot get wet. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"關於「主纜乾燥空氣的水分收支」，下列哪一項敘述正確？","questionEn":"Which statement about \"Moisture budget of cable dry-air injection\" is correct?","options":["本州四國連絡橋的檢查發現，舊有懸索橋拆開鍍鋅纏絲後鋼絲已有鏽蝕，因此開發了將乾燥空氣送入主纜內部的系統，並以世界首創的形式用於明石海峽大橋與其他懸索橋。","主纜外面有鍍鋅纏絲與塗裝，內部就不會潮濕。","減振裝置維護得越頻繁，橋梁一定越安全。"],"optionsEn":["Inspections of older Honshu-Shikoku suspension bridges found rust on wires once the galvanised wrapping was removed, so a system injecting dry air into the main cable was developed and used, as a world first, on Akashi Kaikyo and the other suspension bridges.","With galvanised wrapping and paint outside, the cable interior cannot get wet.","The more often dampers are serviced, the safer the bridge must be."],"answer":0,"explanation":"本州四國連絡橋的檢查發現，舊有懸索橋拆開鍍鋅纏絲後鋼絲已有鏽蝕，因此開發了將乾燥空氣送入主纜內部的系統，並以世界首創的形式用於明石海峽大橋與其他懸索橋。 其餘選項是常見誤解。","explanationEn":"Inspections of older Honshu-Shikoku suspension bridges found rust on wires once the galvanised wrapping was removed, so a system injecting dry air into the main cable was developed and used, as a world first, on Akashi Kaikyo and the other suspension bridges. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":45},{"id":"b003-v13-34","title":"主纜乾燥空氣的水分收支：定量估算","titleEn":"Moisture budget of cable dry-air injection: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-33"],"objective":"以數值模型估算「主纜送氣出口濕度」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Cable exhaust humidity” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：25 °C 飽和水氣密度約 23.0 g/m³。送入 15% RH 空氣（3.5 g/m³），出口 40% RH（9.2 g/m³），每立方公尺帶走約 5.7 g。流量 1.0 m³/min 時每日 1,440 m³，約 8.2 kg 水；若段內殘留 50 kg 水，約 6 天才能排除。主纜空隙約 0.989×20% ≈ 0.198 m³/m。數值為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Saturated vapour density at 25 °C is about 23.0 g/m³. Injecting air at 15% RH (3.5 g/m³) with exhaust at 40% RH (9.2 g/m³) removes about 5.7 g per cubic metre. At 1.0 m³/min, 1,440 m³ a day carries about 8.2 kg of water, so 50 kg trapped in a section takes about 6 days to clear. Cable voids are about 0.989×20% ≈ 0.198 m³ per metre. Values are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在每個送氣與排氣口連續記錄溫度、相對濕度與流量，計算各段的露點與水分移除量；排氣濕度持續高於目標時，先檢查包覆氣密與送氣壓力，再於低點開窗目視檢查鋼絲鍍鋅狀態。","observationEn":"How to cross-check: Log temperature, relative humidity and flow continuously at every injection and exhaust point, computing dew point and moisture removal per section; if exhaust humidity stays above target, first check wrapping airtightness and supply pressure, then open an inspection window at a low point to inspect the zinc on the wires.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b003-v13-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"25 °C 飽和水氣密度約 23.0 g/m³。送入 15% RH 空氣（3.5 g/m³），出口 40% RH（9.2 g/m³），每立方公尺帶走約 5.7 g。流量 1.0 m³/min 時每日 1,440 m³，約 8.2 kg 水；若段內殘留 50 kg 水，約 6 天才能排除。主纜空隙約 0.989×20% ≈ 0.198 m³/m。數值為教學假設。","textEn":"Saturated vapour density at 25 °C is about 23.0 g/m³. Injecting air at 15% RH (3.5 g/m³) with exhaust at 40% RH (9.2 g/m³) removes about 5.7 g per cubic metre. At 1.0 m³/min, 1,440 m³ a day carries about 8.2 kg of water, so 50 kg trapped in a section takes about 6 days to clear. Cable voids are about 0.989×20% ≈ 0.198 m³ per metre. Values are teaching assumptions.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"依「主纜乾燥空氣的水分收支」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Moisture budget of cable dry-air injection\", which statement holds?","options":["懸索橋很柔，所以地震對它幾乎沒有影響。","25 °C 飽和水氣密度約 23.0 g/m³。","水中混凝土只要配比強度夠高，澆置方式不影響品質。"],"optionsEn":["A suspension bridge is so flexible that earthquakes hardly affect it.","Saturated vapour density at 25 °C is about 23.0 g/m³.","If the underwater mix is strong enough, the placing method does not affect quality."],"answer":1,"explanation":"25 °C 飽和水氣密度約 23.0 g/m³。 重算時請保留單位。","explanationEn":"Saturated vapour density at 25 °C is about 23.0 g/m³. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":46},{"id":"b003-v13-35","title":"主纜乾燥空氣的水分收支：試驗與驗證","titleEn":"Moisture budget of cable dry-air injection: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「主纜送氣出口濕度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Cable exhaust humidity” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在每個送氣與排氣口連續記錄溫度、相對濕度與流量，計算各段的露點與水分移除量；排氣濕度持續高於目標時，先檢查包覆氣密與送氣壓力，再於低點開窗目視檢查鋼絲鍍鋅狀態。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Log temperature, relative humidity and flow continuously at every injection and exhaust point, computing dew point and moisture removal per section; if exhaust humidity stays above target, first check wrapping airtightness and supply pressure, then open an inspection window at a low point to inspect the zinc on the wires. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：把每個區段的排氣濕度、流量與設備運轉狀態納入中央監控與警報，維修紀錄須連結到區段編號；包覆修補、索夾更換等作業後要重新做氣密與流量確認，才算結案。","observationEn":"Site practice: Bring exhaust humidity, flow and equipment status for every section into central monitoring with alarms, link maintenance records to section numbers, and close out wrapping repairs or cable-band work only after airtightness and flow are re-verified.","failure":"注意干擾：包覆破損或索夾密封失效會讓乾燥空氣從近端漏出，遠端仍潮濕，平均讀值卻看似正常；送氣設備故障未被警報偵測時，纜內濕度數週內就可能回升到腐蝕門檻以上。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Damaged wrapping or failed cable-band seals let dry air escape near the inlet while the far end stays wet, even though average readings look normal; an equipment fault not caught by alarms can let internal humidity climb above the corrosion threshold within weeks. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b003-v13-35-k1","title":"驗證方法","titleEn":"Verification method","text":"在每個送氣與排氣口連續記錄溫度、相對濕度與流量，計算各段的露點與水分移除量；排氣濕度持續高於目標時，先檢查包覆氣密與送氣壓力，再於低點開窗目視檢查鋼絲鍍鋅狀態。","textEn":"Log temperature, relative humidity and flow continuously at every injection and exhaust point, computing dew point and moisture removal per section; if exhaust humidity stays above target, first check wrapping airtightness and supply pressure, then open an inspection window at a low point to inspect the zinc on the wires.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-35-k2","title":"現場實務","titleEn":"Site practice","text":"把每個區段的排氣濕度、流量與設備運轉狀態納入中央監控與警報，維修紀錄須連結到區段編號；包覆修補、索夾更換等作業後要重新做氣密與流量確認，才算結案。","textEn":"Bring exhaust humidity, flow and equipment status for every section into central monitoring with alarms, link maintenance records to section numbers, and close out wrapping repairs or cable-band work only after airtightness and flow are re-verified.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"要驗證「主纜乾燥空氣的水分收支」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Moisture budget of cable dry-air injection\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","地震後只要把橋塔推回原位，就能維持原設計線形。","在每個送氣與排氣口連續記錄溫度、相對濕度與流量，計算各段的露點與水分移除量；排氣濕度持續高於目標時，先檢查包覆氣密與送氣壓力，再於低點開窗目視檢查鋼絲鍍鋅狀態。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","After an earthquake you simply push the towers back to restore the design profile.","Log temperature, relative humidity and flow continuously at every injection and exhaust point, computing dew point and moisture removal per section."],"answer":2,"explanation":"在每個送氣與排氣口連續記錄溫度、相對濕度與流量，計算各段的露點與水分移除量；排氣濕度持續高於目標時，先檢查包覆氣密與送氣壓力，再於低點開窗目視檢查鋼絲鍍鋅狀態。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Log temperature, relative humidity and flow continuously at every injection and exhaust point, computing dew point and moisture removal per section; if exhaust humidity stays above target, first check wrapping airtightness and supply pressure, then open an inspection window at a low point to inspect the zinc on the wires. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":47},{"id":"b003-v13-36","title":"主纜乾燥空氣的水分收支：失效診斷","titleEn":"Moisture budget of cable dry-air injection: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-35"],"objective":"從症狀倒推「主纜送氣出口濕度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Cable exhaust humidity” and propose discriminating checks, corrective actions and prevention.","instruction":"包覆破損或索夾密封失效會讓乾燥空氣從近端漏出，遠端仍潮濕，平均讀值卻看似正常；送氣設備故障未被警報偵測時，纜內濕度數週內就可能回升到腐蝕門檻以上。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Damaged wrapping or failed cable-band seals let dry air escape near the inlet while the far end stays wet, even though average readings look normal; an equipment fault not caught by alarms can let internal humidity climb above the corrosion threshold within weeks. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：乾燥空氣沿主纜空隙流動，一路蒸發並帶走殘留水分，最後從排氣口排出，排氣口的濕度就是纜內是否已乾燥的指標。","observationEn":"Link to the mechanism: The dry air travels through the cable voids, evaporating and carrying away trapped moisture before leaving at exhaust points, so exhaust humidity is the indicator of whether the cable interior is dry.","failure":"誤判風險：若相信「主纜外面有鍍鋅纏絲與塗裝，內部就不會潮濕。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"With galvanised wrapping and paint outside, the cable interior cannot get wet.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b003-v13-36-k1","title":"失效模式","titleEn":"Failure mode","text":"包覆破損或索夾密封失效會讓乾燥空氣從近端漏出，遠端仍潮濕，平均讀值卻看似正常；送氣設備故障未被警報偵測時，纜內濕度數週內就可能回升到腐蝕門檻以上。","textEn":"Damaged wrapping or failed cable-band seals let dry air escape near the inlet while the far end stays wet, even though average readings look normal; an equipment fault not caught by alarms can let internal humidity climb above the corrosion threshold within weeks.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"在「主纜乾燥空氣的水分收支」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Moisture budget of cable dry-air injection\" shows distress, which diagnosis is most reasonable?","options":["包覆破損或索夾密封失效會讓乾燥空氣從近端漏出，遠端仍潮濕，平均讀值卻看似正常；送氣設備故障未被警報偵測時，纜內濕度數週內就可能回升到腐蝕門檻以上。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","減振裝置維護得越頻繁，橋梁一定越安全。"],"optionsEn":["Damaged wrapping or failed cable-band seals let dry air escape near the inlet while the far end stays wet, even though average readings look normal.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","The more often dampers are serviced, the safer the bridge must be."],"answer":0,"explanation":"包覆破損或索夾密封失效會讓乾燥空氣從近端漏出，遠端仍潮濕，平均讀值卻看似正常；送氣設備故障未被警報偵測時，纜內濕度數週內就可能回升到腐蝕門檻以上。 需以量測區分可能原因。","explanationEn":"Damaged wrapping or failed cable-band seals let dry air escape near the inlet while the far end stays wet, even though average readings look normal; an equipment fault not caught by alarms can let internal humidity climb above the corrosion threshold within weeks. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":48},{"id":"b003-v13-37","title":"減振裝置維護與 200 年資產管理：機制與傳力路徑","titleEn":"Damper upkeep and 200-year asset management: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-36"],"objective":"說明「塔內 TMD 與 200 年目標」如何影響明石海峽大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “Tower TMDs and 200-year target” governs force, deformation or durability in “Akashi Kaikyo Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"本州四國連絡橋的維護方針以 200 年以上的長期使用為目標，以預防保全與資產管理把生命週期成本降到最低。明石海峽主塔為十字形斷面，風洞試驗顯示若無減振裝置，塔在橫向風中振幅可達約 95 cm，裝設 TMD 與附加阻尼器後約 10 cm，容許值 30 cm；公開簡報列出共約 40 組 TMD 與 8 組附加阻尼器。營運後實測塔位移小於約 2 cm，營運單位因而研究把減振裝置的維護週期由每 5 年延長到約 14 年。這是以監測數據調整維護投入的典型案例。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「塔內 TMD 與 200 年目標」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"The Honshu-Shikoku maintenance policy targets service of 200 years or more, minimising life-cycle cost through preventive maintenance and asset management. The Akashi Kaikyo towers have a cruciform section; wind-tunnel tests showed transverse-wind amplitudes of about 95 cm without dampers and about 10 cm with TMDs and additional dampers, against an allowable 30 cm, and a public presentation lists about 40 TMDs and 8 additional dampers. Measured tower displacement in service stayed below about 2 cm, so the operator studied extending the damper maintenance interval from every 5 years to about 14 years, a typical case of using monitoring data to tune maintenance effort. Mentor task: draw a free-body or load-path diagram showing how loads pass through “Tower TMDs and 200-year target” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：渦振振幅約與總阻尼成反比。","observationEn":"Order-of-magnitude cue: Vortex-induced amplitude is roughly inversely proportional to total damping.","failure":"常見誤解：「減振裝置維護得越頻繁，橋梁一定越安全。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The more often dampers are serviced, the safer the bridge must be.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「塔內 TMD 與 200 年目標」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “Tower TMDs and 200-year target”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b003-v13-37-k1","title":"減振裝置維護與 200 年資產管理","titleEn":"Damper upkeep and 200-year asset management","text":"本州四國連絡橋的維護方針以 200 年以上的長期使用為目標，以預防保全與資產管理把生命週期成本降到最低。明石海峽主塔為十字形斷面，風洞試驗顯示若無減振裝置，塔在橫向風中振幅可達約 95 cm，裝設 TMD 與附加阻尼器後約 10 cm，容許值 30 cm；公開簡報列出共約 40 組 TMD 與 8 組附加阻尼器。","textEn":"The Honshu-Shikoku maintenance policy targets service of 200 years or more, minimising life-cycle cost through preventive maintenance and asset management. The Akashi Kaikyo towers have a cruciform section; wind-tunnel tests showed transverse-wind amplitudes of about 95 cm without dampers and about 10 cm with TMDs and additional dampers, against an allowable 30 cm, and a public presentation lists about 40 TMDs and 8 additional dampers.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：減振裝置維護得越頻繁，橋梁一定越安全。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The more often dampers are serviced, the safer the bridge must be. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"關於「減振裝置維護與 200 年資產管理」，下列哪一項敘述正確？","questionEn":"Which statement about \"Damper upkeep and 200-year asset management\" is correct?","options":["減振裝置維護得越頻繁，橋梁一定越安全。","本州四國連絡橋的維護方針以 200 年以上的長期使用為目標，以預防保全與資產管理把生命週期成本降到最低。","桁架加勁梁很深很重，所以不會發生顫振。"],"optionsEn":["The more often dampers are serviced, the safer the bridge must be.","The Honshu-Shikoku maintenance policy targets service of 200 years or more, minimising life-cycle cost through preventive maintenance and asset management.","A truss stiffening girder is deep and heavy, so it cannot flutter."],"answer":1,"explanation":"本州四國連絡橋的維護方針以 200 年以上的長期使用為目標，以預防保全與資產管理把生命週期成本降到最低。 其餘選項是常見誤解。","explanationEn":"The Honshu-Shikoku maintenance policy targets service of 200 years or more, minimising life-cycle cost through preventive maintenance and asset management. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":49},{"id":"b003-v13-38","title":"減振裝置維護與 200 年資產管理：定量估算","titleEn":"Damper upkeep and 200-year asset management: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-37"],"objective":"以數值模型估算「塔內 TMD 與 200 年目標」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Tower TMDs and 200-year target” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：渦振振幅約與總阻尼成反比。設塔結構阻尼 ζ_s = 0.5%，95 cm 降到 10 cm 需總阻尼 0.5%×95/10 ≈ 4.75%，即 TMD 附加約 4.25%；要符合 30 cm 只需 0.5%×95/30 ≈ 1.58%。若 TMD 劣化使附加阻尼減半，總阻尼約 2.6%，振幅約 95×0.5/2.6 ≈ 18 cm，仍低於容許值。阻尼比為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Vortex-induced amplitude is roughly inversely proportional to total damping. With tower damping ζ_s = 0.5%, cutting 95 cm to 10 cm needs about 0.5%×95/10 ≈ 4.75% in total, so the TMDs add about 4.25%; meeting 30 cm needs only 0.5%×95/30 ≈ 1.58%. If TMD ageing halves the added damping, the total is about 2.6% and the amplitude about 95×0.5/2.6 ≈ 18 cm, still within the limit. Damping ratios are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以塔內加速度與位移長期紀錄，篩選可能引發振動的強風事件，比較實測振幅與設計預測；定期抽驗 TMD 的頻率與阻尼係數，並做阻尼變化 ±20%、±50% 的敏感度分析，確認延長維護週期後仍滿足容許位移。","observationEn":"How to cross-check: Use long-term tower acceleration and displacement records to pick out strong-wind events capable of exciting vibration and compare measured amplitudes with design predictions; periodically spot-check TMD frequency and damping coefficient, and run sensitivity analyses for ±20% and ±50% damping changes to confirm that the allowable displacement is still met with a longer interval.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b003-v13-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"渦振振幅約與總阻尼成反比。設塔結構阻尼 ζ_s = 0.5%，95 cm 降到 10 cm 需總阻尼 0.5%×95/10 ≈ 4.75%，即 TMD 附加約 4.25%；要符合 30 cm 只需 0.5%×95/30 ≈ 1.58%。若 TMD 劣化使附加阻尼減半，總阻尼約 2.6%，振幅約 95×0.5/2.6 ≈ 18 cm，仍低於容許值。阻尼比為教學假設。","textEn":"Vortex-induced amplitude is roughly inversely proportional to total damping. With tower damping ζ_s = 0.5%, cutting 95 cm to 10 cm needs about 0.5%×95/10 ≈ 4.75% in total, so the TMDs add about 4.25%; meeting 30 cm needs only 0.5%×95/30 ≈ 1.58%. If TMD ageing halves the added damping, the total is about 2.6% and the amplitude about 95×0.5/2.6 ≈ 18 cm, still within the limit. Damping ratios are teaching assumptions.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"依「減振裝置維護與 200 年資產管理」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Damper upkeep and 200-year asset management\", which statement holds?","options":["鋼絲強度越高，主纜就越不需要防蝕。","索股垂度只要白天量一次，誤差幾公分不影響主纜受力。","渦振振幅約與總阻尼成反比。"],"optionsEn":["The stronger the wire, the less corrosion protection the cable needs.","Measuring strand sag once in daytime is fine; a few centimetres of error do not affect cable forces.","Vortex-induced amplitude is roughly inversely proportional to total damping."],"answer":2,"explanation":"渦振振幅約與總阻尼成反比。 重算時請保留單位。","explanationEn":"Vortex-induced amplitude is roughly inversely proportional to total damping. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":50},{"id":"b003-v13-39","title":"減振裝置維護與 200 年資產管理：試驗與驗證","titleEn":"Damper upkeep and 200-year asset management: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「塔內 TMD 與 200 年目標」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Tower TMDs and 200-year target” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以塔內加速度與位移長期紀錄，篩選可能引發振動的強風事件，比較實測振幅與設計預測；定期抽驗 TMD 的頻率與阻尼係數，並做阻尼變化 ±20%、±50% 的敏感度分析，確認延長維護週期後仍滿足容許位移。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use long-term tower acceleration and displacement records to pick out strong-wind events capable of exciting vibration and compare measured amplitudes with design predictions; periodically spot-check TMD frequency and damping coefficient, and run sensitivity analyses for ±20% and ±50% damping changes to confirm that the allowable displacement is still met with a longer interval. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：任何維護週期的延長都要附上監測證據、敏感度分析與重新評估的觸發條件（例如觀測到某風速以上的事件或振幅超過門檻），並由業主的技術委員會核准；檢查與修繕紀錄納入資料庫以 PDCA 循環更新計畫。","observationEn":"Site practice: Any extension of a maintenance interval must come with monitoring evidence, sensitivity analysis and re-assessment triggers (such as an event above a given wind speed or amplitude above a threshold), approved by the owner's technical committee; inspection and repair records go into the database so the plan is updated through a PDCA cycle.","failure":"注意干擾：若不看監測數據而一律縮短週期，維護成本與封閉作業增加卻無性能收益；反之若沒有敏感度分析就延長週期，TMD 卡滯或失調可能在下一次強風時才被發現，塔與索鞍承受未預期的反覆應力。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Shortening intervals regardless of monitoring data adds cost and closures for no performance gain; extending them without sensitivity analysis can leave a stuck or detuned TMD undiscovered until the next strong wind, exposing towers and saddles to unexpected cyclic stress. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b003-v13-39-k1","title":"驗證方法","titleEn":"Verification method","text":"以塔內加速度與位移長期紀錄，篩選可能引發振動的強風事件，比較實測振幅與設計預測；定期抽驗 TMD 的頻率與阻尼係數，並做阻尼變化 ±20%、±50% 的敏感度分析，確認延長維護週期後仍滿足容許位移。","textEn":"Use long-term tower acceleration and displacement records to pick out strong-wind events capable of exciting vibration and compare measured amplitudes with design predictions; periodically spot-check TMD frequency and damping coefficient, and run sensitivity analyses for ±20% and ±50% damping changes to confirm that the allowable displacement is still met with a longer interval.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-39-k2","title":"現場實務","titleEn":"Site practice","text":"任何維護週期的延長都要附上監測證據、敏感度分析與重新評估的觸發條件（例如觀測到某風速以上的事件或振幅超過門檻），並由業主的技術委員會核准；檢查與修繕紀錄納入資料庫以 PDCA 循環更新計畫。","textEn":"Any extension of a maintenance interval must come with monitoring evidence, sensitivity analysis and re-assessment triggers (such as an event above a given wind speed or amplitude above a threshold), approved by the owner's technical committee; inspection and repair records go into the database so the plan is updated through a PDCA cycle.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"要驗證「減振裝置維護與 200 年資產管理」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Damper upkeep and 200-year asset management\"?","options":["以塔內加速度與位移長期紀錄，篩選可能引發振動的強風事件，比較實測振幅與設計預測。","不確定度太難估計，報告中只寫最佳值即可。","全橋模型的風速必須和實橋一樣，試驗才有意義。"],"optionsEn":["Use long-term tower acceleration and displacement records to pick out strong-wind events capable of exciting vibration and compare measured amplitudes with design predictions.","Uncertainty is too hard to estimate, so the report may state only the best value.","A full-bridge model is only meaningful if tested at the same wind speed as the real bridge."],"answer":0,"explanation":"以塔內加速度與位移長期紀錄，篩選可能引發振動的強風事件，比較實測振幅與設計預測；定期抽驗 TMD 的頻率與阻尼係數，並做阻尼變化 ±20%、±50% 的敏感度分析，確認延長維護週期後仍滿足容許位移。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use long-term tower acceleration and displacement records to pick out strong-wind events capable of exciting vibration and compare measured amplitudes with design predictions; periodically spot-check TMD frequency and damping coefficient, and run sensitivity analyses for ±20% and ±50% damping changes to confirm that the allowable displacement is still met with a longer interval. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":51},{"id":"b003-v13-40","title":"減振裝置維護與 200 年資產管理：失效診斷","titleEn":"Damper upkeep and 200-year asset management: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"],"prerequisiteIds":["b003-v13-39"],"objective":"從症狀倒推「塔內 TMD 與 200 年目標」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Tower TMDs and 200-year target” and propose discriminating checks, corrective actions and prevention.","instruction":"若不看監測數據而一律縮短週期，維護成本與封閉作業增加卻無性能收益；反之若沒有敏感度分析就延長週期，TMD 卡滯或失調可能在下一次強風時才被發現，塔與索鞍承受未預期的反覆應力。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Shortening intervals regardless of monitoring data adds cost and closures for no performance gain; extending them without sensitivity analysis can leave a stuck or detuned TMD undiscovered until the next strong wind, exposing towers and saddles to unexpected cyclic stress. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：這是以監測數據調整維護投入的典型案例。","observationEn":"Link to the mechanism: Measured tower displacement in service stayed below about 2 cm, so the operator studied extending the damper maintenance interval from every 5 years to about 14 years, a typical case of using monitoring data to tune maintenance effort.","failure":"誤判風險：若相信「減振裝置維護得越頻繁，橋梁一定越安全。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The more often dampers are serviced, the safer the bridge must be.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b003-v13-40-k1","title":"失效模式","titleEn":"Failure mode","text":"若不看監測數據而一律縮短週期，維護成本與封閉作業增加卻無性能收益；反之若沒有敏感度分析就延長週期，TMD 卡滯或失調可能在下一次強風時才被發現，塔與索鞍承受未預期的反覆應力。","textEn":"Shortening intervals regardless of monitoring data adds cost and closures for no performance gain; extending them without sensitivity analysis can leave a stuck or detuned TMD undiscovered until the next strong wind, exposing towers and saddles to unexpected cyclic stress.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]},{"id":"b003-v13-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v13s-jb-honshi-maintenance-super","v13s-jb-honshi-construction-material","v13s-wcee-akashi-seismic","v13s-iaarc-akashi-caisson-concrete","v13s-piarc-akashi-tower-dampers"]}],"quiz":{"question":"在「減振裝置維護與 200 年資產管理」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Damper upkeep and 200-year asset management\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","若不看監測數據而一律縮短週期，維護成本與封閉作業增加卻無性能收益。","桁架加勁梁很深很重，所以不會發生顫振。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Shortening intervals regardless of monitoring data adds cost and closures for no performance gain.","A truss stiffening girder is deep and heavy, so it cannot flutter."],"answer":1,"explanation":"若不看監測數據而一律縮短週期，維護成本與封閉作業增加卻無性能收益；反之若沒有敏感度分析就延長週期，TMD 卡滯或失調可能在下一次強風時才被發現，塔與索鞍承受未預期的反覆應力。 需以量測區分可能原因。","explanationEn":"Shortening intervals regardless of monitoring data adds cost and closures for no performance gain; extending them without sensitivity analysis can leave a stuck or detuned TMD undiscovered until the next strong wind, exposing towers and saddles to unexpected cyclic stress. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":52}],"order":8}],"title":"明石海峽大橋","titleEn":"Akashi Kaikyo Bridge","summary":"從海峽條件到主纜防蝕，拆解懸索橋的受力、施工幾何與營運證據。","summaryEn":"Trace a suspension bridge from strait conditions to cable corrosion protection through load paths, construction geometry and operating evidence.","scope":"以公開資料建立的原創教學分解；所有步驟為紙上、數位模型與證據判讀練習。自繪的示意與自設資料必須標示假設；本站未提供現地工程資料，亦不是核准施工、設備操作或水質放行程序。","scopeEn":"Original educational decomposition of public information. Every step is a paper, digital-model or evidence-interpretation exercise. Label assumptions in self-drawn diagrams and invented data; this site does not supply field engineering records or approved construction, operating or water-release procedures.","diagram":{"type":"suspension","labels":["地盤與錨碇","橋塔","主纜","吊索與橋面","監測"],"labelsEn":["Ground and anchorages","Towers","Main cables","Hangers and deck","Monitoring"],"original":true,"notToScale":true},"stepCount":52,"estimatedMinutes":1240,"curriculumVersion":6,"enrichmentVersion":13,"learningTrack":"structures","learningSubdiscipline":"st-suspension","learningTags":["structures","st-suspension","suspension"],"subcategory":"st-suspension","subcategoryTitle":"懸索橋巨作與主纜系統","subcategoryTitleEn":"Suspension bridges and main-cable systems","v13Architecture":{"architectureFamily":"suspension","architectureNodes":[["主塔與塔內 TMD","Towers and tower TMDs"],["PWS 主纜","PWS main cables"],["吊索與螺旋纏絲","Hangers and helical wire"],["桁架加勁梁","Truss stiffening girder"],["設置沉箱與錨碇","Laid-down caissons and anchorages"],["乾燥空氣與監測","Dry air and monitoring"]],"architectureEdges":[[3,2],[2,1],[1,0],[0,4],[1,4],[5,1],[5,0]]},"v13Extension":{"stages":5,"steps":40,"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"延伸練習：假設主跨 l = 1,991 m、垂跨比 n = 1/10（f = 199.1 m），兩條主纜與加勁梁合計恆載 w = 431.6 kN/m（44 t/m）。水平張力 H = w·l²/(8f) = 431.6×1,991²/(8×199.1) ≈ 1,074,000 kN，每纜 537 MN；塔頂最大張力 T = H·√(1+16n²) = 537×1.077 ≈ 578 MN。每纜鋼絲面積 0.791 m²，恆載應力 = 578/0.791 ≈ 731 N/mm²，對 1,760 N/mm² 鋼絲的恆載安全係數約 2.41；若活載與溫度再使張力增加 10%，係數降為約 2.19。若改用 1,570 N/mm² 鋼絲而面積不變，恆載係數只剩約 2.15，這正是公開資料說需要每側兩條纜的原因。地震後跨徑若增加 0.8 m，不可伸長估算垂度減少約 1.46 m。數值為教學假設，不代表明石海峽大橋的設計計算。","textEn":"Extension exercise: assume l = 1,991 m, sag ratio n = 1/10 (f = 199.1 m) and a dead load for both cables and the girder of w = 431.6 kN/m (44 t/m). Horizontal tension H = w·l²/(8f) = 431.6×1,991²/(8×199.1) ≈ 1,074,000 kN, or 537 MN per cable; maximum tension at the tower T = H·√(1+16n²) = 537×1.077 ≈ 578 MN. With 0.791 m² of wire per cable the dead-load stress is 578/0.791 ≈ 731 N/mm², a dead-load safety factor of about 2.41 on 1,760 N/mm² wire; if live load and temperature add 10% to tension the factor drops to about 2.19. With 1,570 N/mm² wire and the same area the dead-load factor would be only about 2.15, which is why the public account says two cables per side would have been needed. A 0.8 m span increase after the earthquake reduces sag by about 1.46 m in the inextensible estimate. Values are teaching assumptions, not the design calculations of the Akashi Kaikyo Bridge.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"focus":"以數字深入明石海峽大橋：顫振裕度、高強度鋼絲、設置沉箱、地震後幾何修正與主纜乾燥空氣","focusEn":"Numbers behind Akashi Kaikyo: flutter margin, high-strength wire, laid-down caissons, post-quake geometry correction and dry-air cables"}}};
